// Plan 51 / Migration 189 (Koordinator 31.10.2026): Buchungen ohne Preis zeigen „Kosten unbekannt“ statt 0 €; Summen mit einem unbekannten Teil zeigen den
// bekannten Betrag mit dem Zusatz „dazu N Aufrufe ohne Preis (Kosten unbekannt)“. ohne_preis/aufrufe kommen aus der Datenbank (Migration 189).
const KU_n = x => Math.max(0, Number((x || {}).ohne_preis) || 0);
const KU_alle = x => KU_n(x) > 0 && KU_n(x) >= (Number((x || {}).aufrufe) || 0);
const KU_t = n => n.toLocaleString('de-DE') + (n === 1 ? ' Aufruf' : ' Aufrufe') + ' ohne Preis';
const KU_dazu = n => 'dazu ' + KU_t(n) + ' (Kosten unbekannt)';
const KU_wert = (x, betrag) => KU_alle(x) ? 'Kosten unbekannt (' + KU_t(KU_n(x)) + ')' : KU_n(x) ? betrag + ' · ' + KU_dazu(KU_n(x)) : betrag;
// Einstellungen (ALLY 23, BA5, Stefan 19./20.10.2026): Übersicht (Mein Konto, Organisation, Funktionen, Administration), Profil, Meine Startseite, Mein Kalender,
// Unternehmen und Design (mit App-Symbol, BA4b), Team und Rollen, Postfächer, Absender-Regeln, Einstellungen je Funktion (Talents, Morgen-Briefing, Mail-Assistent, Marketing, Benachrichtigungen
// der Funktion), KI und Budget, Pakete. BA6: Funktionen › Kampagnen (Standard-Erinnerungen, Währung). Daten wie ALLY 8 (ally_web_daten, talents_web_daten, ki_web_daten, superadmin_web_daten). Person anlegen nur über person_vormerken
// (ally_person_vormerken + ALLY 18), Chat-Konto nur zur Anzeige. Formulare mit den Feldern der Datenbank-Aktionen. Liefert nur die Seitenbeschreibung (JSON).
// BA8 (Migration 63): Postfächer › Absender für Systemnachrichten (nur Admin, sy_*), Mein Kalender und Profil › Kalender-Abo (ka_*) und Google Kalender (vorbereitet),
// Team und Rollen › Zugangslink per Mail (sy_person_zugang, nur mit eingestelltem Absender-Postfach).
// Migration 64 (Rollenverwaltung, Stefan 20.10.2026): Team und Rollen › Rollen (ro_*), Rolle je Person mit „Ohne Rolle“, Organisation › Speicherorte (sp_*).
// Migration 66 (Stefan 20.10.2026): „Talents ansehen“ ohne Ändern (Regel R3 entfällt), Profil zeigt „Ohne Rolle“; Speicherorte › eigenen Speicherort einbinden und prüfen
// wie in ALLY 8 (sp_ort_*: ALLY 20 ruft ALLY 11 auf; das Passwort geht nur an ALLY 11, nie in die Datenbank, und wird nie angezeigt).
// BA9 (Migration 68): Speicherorte › „Downloads für Talents“ (sp_download_max, 1–1024 MB); KI und Budget › „Ally-Chat für Talents“ (Standard-KI-Grenze je Talent,
// ki_talent_standard; Übersicht der Talents mit Ally-Chat oder Verbrauch). Team und Rollen › Chat-Konto: Spalte „Für“ (Aufträge für Personen und Talents).
const E = $('Start').first().json;
const D = $input.first().json || {};
const P = E.parameter || {};
const bereich = String(P.bereich || '');
const ADM = D.admin === true, PFR = D.postfaecher_recht === true;
const FU = Array.isArray(D.funktionen) ? D.funktionen : [];
const ZU = D.zustand || {};
const NAMEN = { profil: 'Profil', startseite: 'Startseite', benachrichtigungen: 'Benachrichtigungen', kalender: 'Mein Kalender', unternehmen: 'Unternehmen und Design',
  team: 'Team und Rollen', speicherorte: 'Speicherorte', postfaecher: 'Postfächer', regeln: 'Absender-Regeln', ki: 'KI und Budget', pakete: 'Pakete' };
for (const f of FU) if (f.ziel && !NAMEN[f.ziel]) NAMEN[f.ziel] = String(f.name || f.ziel);
const titel = bereich && NAMEN[bereich] ? NAMEN[bereich] : 'Einstellungen';
const krumen = [{ text: 'Startseite', ziel: { seite: 'start' } }].concat(bereich ? [{ text: 'Einstellungen', ziel: { seite: 'einstellungen' } }, { text: titel }] : [{ text: 'Einstellungen' }]);
const seite = { schluessel: 'einstellungen', art: 'einstellungen', titel, krumen };
const ziel = (b, extra, anker) => ({ seite: 'einstellungen', parameter: Object.assign(b ? { bereich: b } : {}, extra || {}), anker });
const aus = (bl) => [{ json: { inhalt: Object.assign({ seite }, bl) } }];
const fehlt = text => aus({ bloecke: [{ typ: 'hinweis', ton: 'warn', text }, { typ: 'aktion', text: 'Zu den Einstellungen', ziel: ziel('') }] });
if (D.ok !== true) return fehlt('Bitte neu anmelden.');
const sortierung = (tab, erlaubt, std) => { const s = (ZU['einstellungen.' + tab] || {}).sortierung || {};
  return { spalte: erlaubt.includes(s.spalte) ? s.spalte : std, richtung: s.richtung === 'ab' ? 'ab' : 'auf' }; };
const sortiere = (zeilen, so, wert) => zeilen.sort((a, b) => { const x = wert(a, so.spalte), y = wert(b, so.spalte);
  let c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x ?? '').localeCompare(String(y ?? ''), 'de'); return so.richtung === 'ab' ? -c : c; });
// Layout 14 (Plan 41): je = Zeilen je Seite, Vorgabe 20; die Personen geben 10 mit (wie die Anzeige, E8/E10)
const blatt = (tab, n, je = 20) => { const s = Math.max(1, Number((E.seiten || {})[tab]) || 1); return Math.min(s, Math.max(1, Math.ceil(n / je))); };
// BA8: Kalender-Abo (ICS) der eigenen Person – Adresse zum Kopieren, neu erzeugen, beenden
const aboInhalt = K => {
  const A = (K && K.ok === true && K.abo) || null;
  if (!A || (A.aktiv !== true && A.moeglich === false)) return [{ typ: 'text', ton: 'grau', text: 'Das Kalender-Abo ist gerade nicht verfügbar.' }];
  const erkl = 'In der Kalender-App „Kalender abonnieren“ bzw. „Kalender per URL hinzufügen“ wählen und die Adresse einfügen. Die Adresse ist geheim: Wer sie kennt, sieht die Einträge. Änderungen erscheinen je nach App mit Verzögerung.';
  if (A.aktiv !== true) return [{ typ: 'text', text: 'Mit einem Kalender-Abo erscheinen deine Termine, Aufgaben und Deadlines in deiner Kalender-App (zum Beispiel Google Kalender, Apple Kalender oder Outlook). Es enthält die Talents und Kampagnen, die du als Manager oder Managerin betreust.' },
    { typ: 'aktion', text: 'Abo-Adresse erzeugen', aktion: 'ka_abo_neu' }];
  return [A.adresse ? { typ: 'formular', id: 'kalender-abo', aktion: 'ka_abo_neu', frage: 'Neue Abo-Adresse erzeugen? Die bisherige gilt danach nicht mehr.',
      felder: [{ typ: 'anzeige', label: 'Abo-Adresse', wert: String(A.adresse), breite: 'voll', info: erkl }], knoepfe: [{ text: 'Neue Adresse erzeugen', art: 'neben' }] }
      : { typ: 'text', ton: 'warn', text: 'Die Abo-Adresse kann gerade nicht angezeigt werden. Bitte eine neue erzeugen.' },
    { typ: 'paare', eintraege: [{ label: 'Erstellt', wert: String(A.seit || '–') }, { label: 'Zuletzt abgerufen', wert: String(A.letzter_abruf || 'noch nie') }] },
    { typ: 'aktion', text: 'Abo beenden', aktion: 'ka_abo_widerrufen', frage: 'Kalender-Abo beenden? Die Adresse gilt danach nicht mehr.' }];
};

// ---------- Übersicht ----------
if (!bereich) {
  const eintrag = b => ({ text: NAMEN[b], ziel: ziel(b), ziel_text: 'Öffnen' });
  const abschnitte = [
    { id: 'konto', titel: 'Mein Konto', offen_standard: true, inhalt: [{ typ: 'liste', eintraege: ['profil', 'startseite', 'benachrichtigungen', 'kalender'].map(eintrag) }] },
    { id: 'organisation', titel: 'Organisation', offen_standard: true, inhalt: [{ typ: 'liste', leer: 'Keine Einstellungen freigeschaltet.',
      eintraege: [ADM ? 'unternehmen' : '', ADM ? 'team' : '', ADM ? 'speicherorte' : '', PFR ? 'postfaecher' : '', 'regeln'].filter(Boolean).map(eintrag) }] }];
  if (FU.length) abschnitte.push({ id: 'funktionen', titel: 'Funktionen', zahl: String(FU.length), offen_standard: true, inhalt: [{ typ: 'liste', eintraege: FU.map(f => ({ text: String(f.name || ''), ziel: ziel(f.ziel), ziel_text: 'Öffnen' })) }] });
  if (ADM) abschnitte.push({ id: 'administration', titel: 'Administration', offen_standard: true, inhalt: [{ typ: 'liste', eintraege: ['ki', 'pakete'].map(eintrag) }] });
  seite.beschreibung = 'Mein Konto, Organisation, Funktionen und Administration.';
  return aus({ abschnitte });
}

// ---------- Mein Konto › Benachrichtigungen (BA4b, Stefan 20.10.2026): je Art, ob sie in der Glocke erscheint (nur für die eigene Person) ----------
// Daten: Spalte bn = ally_benachrichtigung_schalter_web($1) (Migration 58), Aktion benachrichtigung_schalter (Felder art, glocke; ALLY 20 "Formular lesen").
if (bereich === 'benachrichtigungen') {
  const BN = D.bn || {};
  if (BN.ok !== true) return fehlt('Die Einstellungen zu Benachrichtigungen konnten nicht geladen werden. Bitte die Seite neu laden.');
  const arten = (Array.isArray(BN.arten) ? BN.arten : []).filter(a => /^[a-z0-9_]{1,40}$/.test(String(a.art || '')));
  const anz = arten.filter(a => a.glocke === true).length;
  seite.beschreibung = 'Welche Benachrichtigungen bei dir in der Glocke erscheinen.';
  seite.aktionen = [{ text: 'Alle Benachrichtigungen', ziel: { seite: 'benachrichtigungen' } }];
  const s0 = (ZU['einstellungen.arten'] || {}).sortierung || {};
  const so = ['name', 'glocke'].includes(s0.spalte) ? { spalte: s0.spalte, richtung: s0.richtung === 'ab' ? 'ab' : 'auf' } : {};
  const liste = arten.map((a, i) => [a, i]);
  if (so.spalte) liste.sort((x, y) => { const c = so.spalte === 'glocke' ? (x[0].glocke === y[0].glocke ? 0 : x[0].glocke ? -1 : 1) : String(x[0].name || '').localeCompare(String(y[0].name || ''), 'de');
    return (so.richtung === 'ab' ? -c : c) || x[1] - y[1]; });
  const zeilen = liste.map(([a]) => ({ zellen: {
    name: { text: String(a.name || a.art), fett: true, neben: String(a.beschreibung || '') },
    glocke: { marke: a.glocke === true ? { text: 'erscheint', ton: 'ok' } : { text: 'aus', ton: 'grau' } },
    aktion: { aktion: { text: a.glocke === true ? 'Ausschalten' : 'Einschalten', label: (a.glocke === true ? 'Ausschalten: ' : 'Einschalten: ') + String(a.name || a.art),
      aktion: 'benachrichtigung_schalter', werte: { art: String(a.art), glocke: a.glocke === true ? '0' : '1' } } } } }));
  return aus({ abschnitte: [{ id: 'arten', titel: 'In der Glocke', zahl: anz + ' von ' + arten.length, offen_standard: true,
    info: 'Gilt nur für dich. Ausgeschaltete Arten erscheinen weder in der Glocke noch unter „Alle Benachrichtigungen“. Nachrichten im Chat sind davon nicht betroffen.',
    inhalt: [{ typ: 'tabelle', id: 'arten', titel: 'Arten von Benachrichtigungen', spalten: [{ schluessel: 'name', titel: 'Art', sortierbar: true }, { schluessel: 'glocke', titel: 'In der Glocke', sortierbar: true },
      { schluessel: 'aktion', titel: 'Aktion' }], zeilen, sortierung: so, seite: 1, je_seite: 50, gesamt: zeilen.length, leer: 'Keine Arten von Benachrichtigungen.' }] }] });
}

// ---------- Team und Rollen ----------
// Rollenverwaltung (Migration 64, Stefan 20.10.2026): Rolle Admin fest, alle weiteren Rollen legt der Admin an (ro_*: anlegen, umbenennen, beschreiben, Rechte, archivieren,
// wieder aktivieren; nie löschen). Rechte aus dem Katalog der gebuchten Pakete (ally_rollen_ui), Talent-Rechte mit Reichweite „nur zugeordnete“ oder „alle“.
// Person: Rolle oder „Ohne Rolle“ (person_rolle) und eigene Rechte (B5d). B6 (Migration 167): einzeln vergebene Rechte der bisherigen Oberfläche sind eigene Rechte;
// „Ordner freigeben“ am eigenen Speicherort steht im Katalog (Rolle und eigene Rechte), nicht mehr als eigene Zeile.
if (bereich === 'team') {
  if (!ADM) return fehlt('Team und Rollen verwaltet eine Person mit der Rolle Admin.');
  const W = D.w || {};
  const RO = D.ro && D.ro.ok === true && D.ro.darf === true ? D.ro : {};
  seite.beschreibung = 'Personen, ihre Rollen und was jede Rolle darf.';
  const personen = Array.isArray(W.personen) ? W.personen : [];
  const rollen = Array.isArray(RO.rollen) ? RO.rollen : [];
  const katalog = Array.isArray(RO.katalog) ? RO.katalog : [];
  const RP = {}; for (const x of (Array.isArray(RO.personen) ? RO.personen : [])) RP[x.id] = x;
  const rechte = (Array.isArray(W.rechte_liste) ? W.rechte_liste : []).filter(r => !['admin', 'superadmin'].includes(r.schluessel));
  const pfs = Array.isArray(W.postfaecher) ? W.postfaecher : [];
  const TL = ((D.t || {}).ok === true ? D.t.talents : []) || [];
  const talentsVon = id => TL.filter(t => t.status === 'aktiv' && (t.zustaendig || []).some(z => z.id === id));
  const pfVon = id => pfs.filter(p => (p.personen || []).includes(id));
  const status = p => !p.ally_aktiv ? { text: 'deaktiviert', ton: 'grau', r: 4 } : !p.hat_zugang ? { text: 'ohne Zugang', ton: 'grau', r: 3 } : !p.zugang_aktiv ? { text: 'gesperrt', ton: 'warn', r: 2 }
    : (!p.passwort_gesetzt && p.startcode_offen) ? { text: 'eingeladen', ton: 'grau', r: 1 } : { text: 'aktiv', ton: 'ok', r: 0 };
  const rolleText = p => p.rolle ? String(p.rolle_name || p.rolle) + ((RP[p.id] || {}).rolle_archiviert ? ' (archiviert)' : '') : 'Ohne Rolle';
  const so = sortierung('personen', ['name', 'rolle', 'talents', 'postfaecher', 'status'], 'name');
  const wert = (p, sp) => sp === 'name' ? String(p.name || '').toLowerCase() : sp === 'rolle' ? rolleText(p) : sp === 'talents' ? talentsVon(p.id).length : sp === 'postfaecher' ? pfVon(p.id).length : status(p).r;
  const liste = sortiere(personen.slice(), so, wert);
  // Layout 14 (Plan 41, Koordinator 24.10.2026, E8/E10): 10 je Seite wie die Anzeige – „Alle markieren“ zählt dann genau die sichtbare Seite
  const JE = 10;
  const bl = blatt('personen', liste.length, JE);
  const gewaehlt = personen.find(p => p.id === P.person) || null;
  const abschnitte = [{ id: 'personen', titel: 'Personen', zahl: String(personen.length), offen_standard: true, inhalt: [{ typ: 'tabelle', id: 'personen', titel: 'Personen',
    spalten: [{ schluessel: 'name', titel: 'Name', sortierbar: true }, { schluessel: 'rolle', titel: 'Rolle', sortierbar: true }, { schluessel: 'talents', titel: 'Talents', sortierbar: true, ausrichtung: 'rechts' },
      { schluessel: 'postfaecher', titel: 'Postfächer', sortierbar: true, ausrichtung: 'rechts' }, { schluessel: 'status', titel: 'Status', sortierbar: true }],
    zeilen: liste.slice((bl - 1) * JE, bl * JE).map(p => ({ aktiv: gewaehlt === p, zellen: { name: { text: String(p.name || ''), ziel: ziel('team', { person: p.id }) },
      rolle: rolleText(p) + (p.superadmin ? ' · Superadmin' : ''), talents: p.rolle === 'admin' ? 'alle' : String(talentsVon(p.id).length || '–'),
      postfaecher: String(pfVon(p.id).length || '–'), status: { marke: (({ text, ton }) => ({ text, ton }))(status(p)) } } })),
    sortierung: so, seite: bl, je_seite: JE, gesamt: liste.length, leer: 'Noch keine Personen.' }] }];

  // Rollen: Tabelle, Rolle anlegen (Dialog), gewählte Rolle im Seitenfenster
  const fenster = [];
  const gewRolle = rollen.find(r => r.schluessel === P.rolle) || null;
  const aktivP = r => (Array.isArray(r.personen) ? r.personen : []).filter(x => x.aktiv);
  const RW = [{ wert: '', text: 'Kein Recht' }, { wert: 'zugeordnet', text: 'Nur zugeordnete Talents' }, { wert: 'alle', text: 'Alle Talents' }];
  // B5b (Migration 163, Prüfbericht M161 N1): in Rollen der Art talent ist „Eigenes Profil“ fest (Häkchen gesperrt, mit Hinweis)
  // B5c (Migration 165): Rollen der Art talent zeigen nur die Gruppe Talent-Bereich (alle Rechte nur_selbst). zusatz: { name, wenn } für „Rolle anlegen“
  // (Häkchen der Talent-Gruppe unter eigenem Namen, Felder nur bei passender Auswahl „Rolle für“).
  const nurTalent = g => (Array.isArray(g.rechte) ? g.rechte : []).length > 0 && g.rechte.every(r => r && r.nur_selbst === true);
  const katalogFelder = (hat, art, zusatz) => {
    const f = [];
    katalog.forEach((g, i) => {
      // B5d (Migration 166): im Person-Fenster ohne Rechte für die eigenen Daten eines Talents (zusatz.ohneSelbst); Abweichung von der Rolle (zusatz.basis) markiert
      const R = (Array.isArray(g.rechte) ? g.rechte : []).filter(r => !(zusatz && zusatz.ohneSelbst && r.nur_selbst === true));
      if (!R.length) return;
      if (art === 'talent' && !nurTalent(g)) return;
      const BA = zusatz && zusatz.basis ? zusatz.basis : null;
      const abw = k => BA && String(hat[k] === undefined ? '' : hat[k]) !== String(BA[k] === undefined ? '' : BA[k]);
      const mitRw = R.filter(r => r.reichweite === true), ohne = R.filter(r => r.reichweite !== true);
      if (mitRw.length) {
        f.push({ typ: 'anzeige', name: 'gruppe_' + i, label: String(g.gruppe || ''), wert: 'Je Recht: kein Recht, nur zugeordnete Talents oder alle Talents.', breite: 'voll',
          info: ['Zugeordnete Talents: Talents, die die Person als Manager oder Managerin betreut, und Kampagnen mit diesen Talents.',
            '„Talents ansehen“ allein erlaubt keine Änderungen. Ändern dürfen nur Personen mit „Talents und Kampagnen verwalten“ (für zugeordnete oder alle Talents).',
            'Honorare und Budgets sieht nur, wer dieses Recht hat. Ein Talent sieht nie Daten anderer Talents.'] });
        for (const r of mitRw) f.push({ typ: 'auswahl', name: 'recht__' + r.schluessel, label: String(r.name || r.schluessel),
          info: abw(r.schluessel) ? [String(r.text || ''), 'Ausnahme: abweichend von der Rolle.'].filter(Boolean) : String(r.text || ''),
          wert: ['zugeordnet', 'alle'].includes(hat[r.schluessel]) ? hat[r.schluessel] : '', optionen: RW });
      }
      if (ohne.length) f.push({ typ: 'mehrfach', name: (zusatz && zusatz.name) || 'rechte', id_zusatz: (art === 'talent' ? 't' : 'g') + i, label: String(g.gruppe || ''), breite: 'voll',
        info: ohne.map(r => String(r.name || '') + ': ' + String(r.text || '')),
        wert: ohne.filter(r => hat[r.schluessel] !== undefined || (art === 'talent' && r.schluessel === 'talent_profil')).map(r => r.schluessel),
        optionen: ohne.map(r => art === 'talent' && r.schluessel === 'talent_profil'
          ? { wert: r.schluessel, text: String(r.name || r.schluessel), gesperrt: true, neben: 'Immer an. Ohne dieses Recht sieht kein Talent sein Profil.' }
          : Object.assign({ wert: r.schluessel, text: String(r.name || r.schluessel) }, abw(r.schluessel) ? { neben: 'Ausnahme: abweichend von der Rolle' } : {})) });
    });
    return zusatz && zusatz.wenn ? f.map(x => Object.assign(x, { zeigen_wenn: zusatz.wenn })) : f;
  };
  // B2 (Migration 156, G2): Vorlagen der Pakete tragen die Marke „Vorlage“ und den Namen des Pakets (Name wie unter Pakete)
  const paketName = k => { const p = (Array.isArray(W.pakete) ? W.pakete : []).find(x => x && x.schluessel === k); return String((p && p.name) || k || ''); };
  const rolleZeile = r => ({ aktiv: gewRolle === r, zellen: { rolle: { text: String(r.name || ''), ziel: ziel('team', { rolle: r.schluessel }, 'a-rollen'), neben: String(r.beschreibung || '') },
    darf: String(r.kurz || ''), personen: String(aktivP(r).length || '–'),
    status: { marke: r.art === 'admin' ? { text: 'fest', ton: 'grau' } : r.archiviert ? { text: 'archiviert', ton: 'grau' } : r.vorlage ? { text: 'Vorlage', ton: 'grau' } : { text: 'aktiv', ton: 'ok' },
      neben: r.vorlage && !r.archiviert ? 'Paket ' + paketName(r.paket) : undefined } } });
  const rolleSpalten = [{ schluessel: 'rolle', titel: 'Rolle' }, { schluessel: 'darf', titel: 'Darf' }, { schluessel: 'personen', titel: 'Personen', ausrichtung: 'rechts' }, { schluessel: 'status', titel: 'Status' }];
  const rAktiv = rollen.filter(r => !r.archiviert), rArchiv = rollen.filter(r => r.archiviert);
  const inhaltR = [{ typ: 'tabelle', id: 'rollen', titel: 'Rollen', spalten: rolleSpalten, zeilen: rAktiv.map(rolleZeile), sortierung: {}, seite: 1, je_seite: 50, gesamt: rAktiv.length,
    leer: 'Noch keine Rollen.' }];
  if (rArchiv.length) inhaltR.push({ typ: 'unterueberschrift', text: 'Archivierte Rollen', info: 'Archivierte Rollen lassen sich nicht zuweisen und geben keine Rechte. Sie bleiben gespeichert und lassen sich wieder aktivieren.' },
    { typ: 'tabelle', id: 'rollen-archiv', titel: 'Archivierte Rollen', spalten: rolleSpalten, zeilen: rArchiv.map(rolleZeile), sortierung: {}, seite: 1, je_seite: 50, gesamt: rArchiv.length });
  if (katalog.length) inhaltR.push({ typ: 'aktion', text: 'Rolle anlegen', fenster: 'rolle-neu' });
  abschnitte.push({ id: 'rollen', titel: 'Rollen', zahl: String(rAktiv.length), offen_standard: !!gewRolle,
    info: 'Die Rolle Admin ist fest und darf alles. Alle weiteren Rollen legst du hier an und gibst ihnen Rechte aus den gebuchten Paketen. Wer keine Rolle hat, sieht nur Startseite, Mein Konto und Benachrichtigungen.',
    inhalt: inhaltR });
  if (katalog.length) fenster.push({ id: 'rolle-neu', art: 'dialog', titel: 'Rolle anlegen', inhalt: [{ typ: 'formular', id: 'rolle-neu', aktion: 'ro_neu', spalten: 2, felder: [
    { typ: 'text', name: 'name', label: 'Name der Rolle', pflicht: true, autocomplete: 'off', breite: 'voll' },
    { typ: 'textbereich', name: 'beschreibung', label: 'Beschreibung', zeilen: 2, breite: 'voll', info: 'Wofür die Rolle gedacht ist. Erscheint in der Liste der Rollen.' }]
    // B5c (Migration 165): Rolle für Team oder für Talents; für Talents nur die Gruppe Talent-Bereich („Eigenes Profil“ fest)
    .concat(katalog.some(nurTalent) ? [{ typ: 'auswahl', name: 'art', label: 'Rolle für', wert: 'eigen', breite: 'voll', optionen: [{ wert: 'eigen', text: 'Team' }, { wert: 'talent', text: 'Talents' }],
        info: 'Rollen für Talents haben nur Rechte aus dem Talent-Bereich. Talents bekommen sie beim Einladen oder im Talent-Profil.' }].concat(
        katalogFelder({}, undefined, { wenn: { feld: 'art', werte: ['eigen'] } }), katalogFelder({}, 'talent', { name: 'rechte_talent', wenn: { feld: 'art', werte: ['talent'] } }))
      : katalogFelder({})),
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Rolle anlegen' }] }] });
  if (gewRolle) {
    const r = gewRolle, ap = aktivP(r), alleP = Array.isArray(r.personen) ? r.personen : [];
    const inhalt = [{ typ: 'paare', eintraege: [{ label: 'Darf', wert: String(r.kurz || '') },
      { label: 'Personen', wert: alleP.length ? alleP.map(x => String(x.name || '') + (x.aktiv ? '' : ' (deaktiviert)')).join(', ') : '–' },
      r.vorlage ? { label: 'Vorlage', wert: 'Vorlage des Pakets ' + paketName(r.paket) + (r.wie_standard === false ? ', vom Standard abweichend' : '') } : null,
      r.archiviert ? { label: 'Archiviert', wert: String(r.archiviert_am || '') } : null].filter(Boolean) }];
    if (r.art === 'admin') inhalt.push({ typ: 'text', ton: 'grau', text: 'Die Rolle Admin ist fest. Sie darf alles in der Organisation und lässt sich nicht ändern.' });
    else if (r.archiviert) inhalt.push({ typ: 'aktion', text: 'Wieder aktivieren', aktion: 'ro_aktivieren', werte: { schluessel: r.schluessel } });
    else {
      const hat = r.rechte && typeof r.rechte === 'object' ? r.rechte : {};
      inhalt.push({ typ: 'formular', id: 'rolle-bearbeiten', aktion: 'ro_speichern', werte: { schluessel: r.schluessel }, titel: 'Bearbeiten', spalten: 2,
        info: ap.length ? 'Änderungen gelten sofort für ' + ap.length + (ap.length === 1 ? ' Person.' : ' Personen.') : undefined,
        felder: [{ typ: 'text', name: 'name', label: 'Name der Rolle', wert: String(r.name || ''), pflicht: true, autocomplete: 'off', breite: 'voll' },
          { typ: 'textbereich', name: 'beschreibung', label: 'Beschreibung', wert: String(r.beschreibung || ''), zeilen: 2, breite: 'voll' }].concat(katalogFelder(hat, r.art)),
        knoepfe: [{ text: 'Speichern' }] });
      // B2 (G2): Vorlagen bleiben immer erhalten (kein Papierkorb); weichen ihre Rechte vom Standard ab, lassen sie sich zurücksetzen (ro_standard)
      if (r.vorlage) {
        if (r.standard && r.wie_standard === false) inhalt.push({ typ: 'aktion', text: 'Auf Standard zurücksetzen', aktion: 'ro_standard', werte: { schluessel: r.schluessel },
          frage: 'Rolle „' + String(r.name || '') + '“ auf den Standard zurücksetzen? Die Rechte werden wieder wie in der Vorlage gesetzt. Name und Beschreibung bleiben.' });
      } else if (ap.length) inhalt.push({ typ: 'text', ton: 'grau', text: 'Archivieren geht erst, wenn keine aktive Person diese Rolle mehr hat.' });
      else inhalt.push({ typ: 'aktion', text: 'Rolle archivieren', aktion: 'ro_archivieren', werte: { schluessel: r.schluessel },
        frage: 'Rolle „' + String(r.name || '') + '“ archivieren? Sie lässt sich dann nicht mehr zuweisen und gibt keine Rechte mehr. Wieder aktivieren geht jederzeit.' });
    }
    fenster.push({ id: 'rolle', art: 'seitenfenster', offen: true, titel: String(r.name || ''), untertitel: String(r.beschreibung || (r.art === 'admin' ? 'Feste Rolle' : 'Rolle')),
      schliessen_ziel: ziel('team', {}, 'a-rollen'), inhalt });
  }

  // Migration 168 (Bauplan B7, F14): Die Liste der Chat-Aufträge liefert die Datenbank nur für Superadmins; sonst entfällt der Abschnitt.
  const AUF = Array.isArray(W.chat_auftraege) ? W.chat_auftraege : null;
  const AST = { offen: ['wartet', 'grau'], in_arbeit: ['läuft', 'grau'], erledigt: ['erledigt', 'ok'], fehler: ['Fehler', 'warn'], abgelaufen: ['abgelaufen', 'warn'] };
  const AART = { anlegen: 'Chat-Konto anlegen', deaktivieren: 'Chat-Konto deaktivieren' };
  if (AUF) abschnitte.push({ id: 'chat', titel: 'Chat-Konten', zahl: String(AUF.length), offen_standard: false, inhalt: [{ typ: 'tabelle', id: 'chat', titel: 'Chat-Konten',
    spalten: [{ schluessel: 'erstellt', titel: 'Zeit' }, { schluessel: 'art', titel: 'Auftrag' }, { schluessel: 'name', titel: 'Für' }, { schluessel: 'status', titel: 'Status' }],
    zeilen: AUF.map(a => ({ zellen: { erstellt: String(a.erstellt || ''), art: AART[a.art] || String(a.art || ''), name: { text: String(a.name || ''), neben: String(a.matrix_user_id || '') },
      status: { marke: { text: (AST[a.status] || [String(a.status || '')])[0], ton: (AST[a.status] || [0, 'grau'])[1] }, neben: String(a.meldung || '') } } })),
    sortierung: {}, seite: 1, je_seite: 20, gesamt: AUF.length, leer: 'Keine Aufträge.' }] });
  // Rollen zur Auswahl: Admin und aktive eigene Rollen; „Ohne Rolle“ zuerst. Die Rolle Talent (Art talent) erst, wenn Personen sie bekommen können (B3)
  const rollenOpt = [{ wert: '', text: 'Ohne Rolle' }].concat(rAktiv.filter(r => r.art !== 'talent').map(r => ({ wert: r.schluessel, text: String(r.name || r.schluessel) })));
  const rolleInfo = 'Was jede Rolle darf, steht unter Rollen. Ohne Rolle: nur Startseite, Mein Konto und Benachrichtigungen.';
  fenster.push({ id: 'einladen', art: 'dialog', titel: 'Person einladen', inhalt: [{ typ: 'formular', id: 'person-neu', aktion: 'person_vormerken', spalten: 2, felder: [
    { typ: 'text', name: 'name', label: 'Name', pflicht: true, autocomplete: 'off' }, { typ: 'email', name: 'email', label: 'E-Mail-Adresse', pflicht: true, autocomplete: 'off' },
    { typ: 'auswahl', name: 'rolle', label: 'Rolle', wert: '', optionen: rollenOpt, breite: 'voll', info: rolleInfo },
    { typ: 'mehrfach', name: 'postfaecher', label: 'Postfächer', breite: 'voll', wert: [], optionen: pfs.map(p => ({ wert: p.adresse, text: String(p.adresse) })) },
    { typ: 'anzeige', name: 'chat', label: 'Chat-Konto', wert: 'wird beim Anlegen automatisch erstellt', breite: 'voll' }],
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Einladen' }] }] });
  if (gewaehlt) {
    const p = gewaehlt, worte = String(p.name || '').split(/\s+/).filter(Boolean), st = status(p), rp = RP[p.id] || {};
    const av = ((worte[0] || '').charAt(0) + (worte.length > 1 ? worte[worte.length - 1].charAt(0) : (worte[0] || '').charAt(1))).toUpperCase();
    const tv = talentsVon(p.id), pv = pfVon(p.id);
    const wirksam = Array.isArray(rp.wirksam) ? rp.wirksam : [];
    const inhalt = [{ typ: 'paare', eintraege: [{ label: 'Status', wert: st.text }, { label: 'Chat-Konto', wert: String(p.chat_benutzer || '–') + (p.chat_deaktiviert ? ' (deaktiviert)' : '') },
      { label: 'Letzte Anmeldung', wert: String(p.letzte_anmeldung || '–') },
      { label: 'Rechte', wert: p.rolle === 'admin' ? 'alle (Admin)' : wirksam.length ? wirksam.join(', ') : 'keine' },
      { label: 'Manager/in für', wert: p.rolle === 'admin' ? 'alle Talents' : tv.length ? tv.slice(0, 5).map(t => String(t.anzeigename || t.name || '')).join(', ') + (tv.length > 5 ? ' und ' + (tv.length - 5) + ' weitere' : '') : '–' },
      { label: 'Postfächer', wert: pv.length ? pv.map(x => x.adresse).join(', ') : '–' }] }];
    if (p.geschuetzt) inhalt.push({ typ: 'hinweis', ton: 'info', text: 'Diese Person ändert nur eine Person mit Superadmin-Recht.' });
    // B3a (Migration 158): Talents stehen als Personen mit der Rolle „Talent“ in der Liste (Stefan, konzept-einstellungen §7 Antwort 3); bis B5 nur Angaben, ändern über das Talent-Profil
    else if (p.talent_id) inhalt.push({ typ: 'hinweis', ton: 'info', text: 'Den Zugang und die Rolle eines Talents änderst du im Talent-Profil.' },
      { typ: 'aktion', text: 'Talent-Profil', ziel: { seite: 'talent', parameter: { id: String(p.talent_id) } } });
    else {
      if (p.ally_aktiv) {
        const opt = rollenOpt.slice();
        if (p.rolle && !opt.some(o => o.wert === p.rolle)) opt.push({ wert: p.rolle, text: rolleText(p) });
        inhalt.push({ typ: 'formular', id: 'person-rolle', aktion: 'person_rolle', werte: { person: p.id }, knoepfe_in_reihe: true, felder: [{ typ: 'auswahl', name: 'rolle', label: 'Rolle', wert: String(p.rolle || ''),
          optionen: opt, info: rolleInfo }], knoepfe: [{ text: 'Rolle speichern', art: 'neben' }] });
        // B5d (Migration 166, Stefan G4): eigene Rechte zusätzlich zur Rolle (plus/minus), wie im Rollen-Fenster; nicht bei der Rolle Admin
        if (p.rolle !== 'admin' && rp.rechte && typeof rp.rechte === 'object' && katalog.length) {
          const nm = String(p.name || '');
          inhalt.push({ typ: 'formular', id: 'person-eigene-rechte', aktion: 'person_eigene_rechte', werte: { person: p.id }, titel: 'Eigene Rechte', spalten: 2,
            info: ['Gelten zusätzlich zur Rolle nur für ' + nm + '. Was von der Rolle abweicht, ist markiert.', 'Weniger als die Rolle geht je Recht nur mit „Kein Recht“.'],
            felder: katalogFelder(rp.rechte, undefined, { ohneSelbst: true, basis: rp.basis && typeof rp.basis === 'object' ? rp.basis : {} }),
            knoepfe: [{ text: 'Rechte speichern', art: 'neben' }] });
        }
        inhalt.push({ typ: 'formular', id: 'person-daten', aktion: 'person_daten', werte: { id: p.id }, titel: 'Name und E-Mail', felder: [{ typ: 'text', name: 'name', label: 'Name', wert: String(p.name || ''), pflicht: true },
          { typ: 'email', name: 'email', label: 'E-Mail-Adresse', wert: String(p.email || '') }], knoepfe: [{ text: 'Speichern', art: 'neben' }] });
        inhalt.push({ typ: 'unterueberschrift', text: 'Zugang' });
        inhalt.push({ typ: 'aktion', text: p.hat_zugang ? 'Neuen Startcode erzeugen' : 'Startcode erzeugen', aktion: 'person_zugang', werte: { id: p.id },
          frage: 'Startcode für ' + String(p.name || '') + ' erzeugen? Ein bisheriges Passwort gilt danach nicht mehr.' });
        // BA8: mit eingestelltem Absender-Postfach zusätzlich ein Zugangslink per Mail (7 Tage, einmal); das bisherige Passwort bleibt bis dahin gültig
        if (D.sy_aktiv === true && p.email && p.zugang_aktiv !== false) inhalt.push({ typ: 'aktion', text: 'Zugangslink per Mail senden', aktion: 'sy_person_zugang', werte: { id: p.id },
          frage: 'Zugangslink an ' + String(p.email) + ' senden? Damit legt ' + String(p.name || '') + ' ein Passwort fest.' });
        if (p.hat_zugang) inhalt.push(p.zugang_aktiv ? { typ: 'aktion', text: 'Zugang sperren', aktion: 'person_sperren', werte: { id: p.id }, frage: 'Zugang von ' + String(p.name || '') + ' sperren?' }
          : { typ: 'aktion', text: 'Zugang freischalten', aktion: 'person_freigeben', werte: { id: p.id } });
        inhalt.push({ typ: 'aktion', text: 'Person deaktivieren', aktion: 'person_deaktivieren', werte: { person: p.id }, frage: String(p.name || '') + ' deaktivieren? Anmeldung und Chat-Konto werden gesperrt.' });
      } else inhalt.push({ typ: 'aktion', text: 'Wieder aktivieren', aktion: 'person_ally', werte: { id: p.id, aktiv: '1' } });
    }
    fenster.push({ id: 'person', art: 'seitenfenster', offen: true, titel: String(p.name || ''), untertitel: String(p.email || ''), avatar: av, schliessen_ziel: ziel('team'), inhalt });
  }
  seite.hauptaktion = { text: 'Person einladen', fenster: 'einladen' };
  return aus({ abschnitte, fenster });
}

// ---------- Organisation › Speicherorte (Migration 64): eingebundene Speicherorte und wer Ordner für Talents freigeben darf (sp_*). Nur Admin. ----------
// Der Admin legt keine Ordner fest; das tun die Personen mit dem Recht. Inhalte liegen nie auf dem Server.
if (bereich === 'speicherorte') {
  if (!ADM) return fehlt('Speicherorte verwaltet eine Person mit der Rolle Admin.');
  const S = D.sp || {};
  if (S.ok !== true || S.darf !== true) return fehlt('Die Speicherorte konnten nicht geladen werden. Bitte die Seite neu laden.');
  const EG = S.eigen || {}, R = Array.isArray(S.rechte) ? S.rechte : [];
  seite.beschreibung = 'Wo Inhalte liegen und wer Ordner mit Talents teilen darf.';
  const ort = [{ typ: 'paare', eintraege: [{ label: 'Server-Ablage', wert: 'nur für Unterlagen von Ally, nie für Inhalte' },
    { label: 'Eigener Speicherort', wert: EG.eingerichtet === true ? String(EG.name || 'eingebunden') + (EG.art ? ' (' + String(EG.art) + ')' : '') : 'noch nicht eingebunden' },
    EG.eingerichtet === true ? { label: 'Geprüft', wert: EG.geprueft ? 'am ' + String(EG.geprueft) : 'noch nicht' } : null,
    EG.eingerichtet === true ? { label: 'Ordner für Inhalte', wert: String(EG.inhalte_ordner || 'Inhalte') } : null].filter(Boolean) }];
  if (EG.paket === false) ort.push({ typ: 'text', ton: 'grau', text: 'Das Paket für einen eigenen Speicherort ist nicht gebucht.' });
  else if (EG.eingerichtet !== true) ort.push({ typ: 'text', ton: 'grau', text: 'Ein eigener Speicherort (WebDAV) ist noch nicht eingebunden.' });
  else if (EG.bereit !== true) ort.push({ typ: 'text', ton: 'warn', text: 'Der Speicherort ist noch nicht geprüft. Bis dahin lassen sich keine Ordner teilen.' });
  const abschnitte = [{ id: 'orte', titel: 'Eingebunden', offen_standard: true,
    info: 'Inhalte wie Content-Dateien und Videos liegen immer im eigenen Speicherort der Organisation, nie auf dem Server. Weitere Cloud-Anbieter lassen sich als Paket buchen.', inhalt: ort }];
  // Migration 66 (Stefan 20.10.2026): eigenen Speicherort einbinden und prüfen wie in ALLY 8 (ablage_web_seite, Prüfen und Speichern über ALLY 11).
  // Das Passwort-Feld bleibt immer leer; leer lassen = bisheriges Passwort (nur bei gleicher Adresse und gleichem Benutzer).
  const AB = D.ab || null;
  if (AB && AB.gebucht === true && AB.darf === true) {
    const ein = [];
    if (AB.zugang_da !== true) ein.push({ typ: 'text', ton: 'warn', text: 'Für den Speicherort sind in n8n noch keine Zugangsdaten angelegt. Bitte die Person fragen, die das System betreut.' });
    else {
      const offen = [Number(AB.offene_belege) > 0 ? Number(AB.offene_belege) + (Number(AB.offene_belege) === 1 ? ' Beleg' : ' Belege') : '',
        Number(AB.offene_themen) > 0 ? Number(AB.offene_themen) + (Number(AB.offene_themen) === 1 ? ' Marketing-Beitrag' : ' Marketing-Beiträge') + ' in Arbeit' : ''].filter(Boolean);
      ein.push({ typ: 'formular', id: 'speicherort-einbinden', aktion: 'sp_ort_speichern', titel: AB.art === 'webdav' ? 'Ändern und erneut prüfen' : 'Einbinden und prüfen', spalten: 2,
        frage: 'Speicherort jetzt prüfen und umstellen? Neue Dateien landen danach dort.',
        info: 'Geprüft werden Ordner, Schreiben und Löschen mit einer kleinen Prüfdatei, die sofort wieder gelöscht wird. Erst danach werden die Zugangsdaten gespeichert und neue Dateien dort abgelegt. Vorhandene Dateien bleiben am bisherigen Ort.',
        felder: [{ typ: 'text', name: 'name', label: 'Bezeichnung', wert: String(AB.name || 'NAS'), pflicht: true, autocomplete: 'off', hinweis: 'Zum Beispiel NAS' },
          { typ: 'text', name: 'adresse', label: 'Adresse (WebDAV)', wert: String(AB.adresse || ''), platzhalter: 'https://nas.firma.de:5006', pflicht: true, autocomplete: 'off',
            info: 'Ohne https geht es nur im eigenen Netz.' },
          { typ: 'text', name: 'benutzer', label: 'Anmeldename', wert: String(AB.benutzer || ''), pflicht: true, autocomplete: 'off' },
          { typ: 'passwort', name: 'passwort', label: 'Passwort', autocomplete: 'new-password', hinweis: AB.benutzer ? 'Leer lassen: bisheriges Passwort' : '',
            info: 'Das Passwort wird verschlüsselt in den Zugangsdaten von n8n gespeichert, nicht in der Datenbank, und hier nie wieder angezeigt.' },
          { typ: 'text', name: 'ordner', label: 'Ordner', wert: String(AB.ordner_ally || ''), platzhalter: '/Dokumente', pflicht: true, autocomplete: 'off', breite: 'voll',
            info: 'Darin landen Berichte, Marketing-Dateien und eingegangene Belege. Verbuchte Belege kommen in den Unterordner Buchhaltung, solange unten nichts anderes eingestellt ist.' +
              (offen.length ? ' Noch offen: ' + offen.join(' und ') + '. Deren Dateien werden nach dem Umstellen nicht mehr gefunden, besser erst danach umstellen.' : '') }],
        knoepfe: [{ text: 'Prüfen und speichern' }] });
      if (AB.art === 'webdav' && AB.belege === true) ein.push({ typ: 'formular', id: 'speicherort-belege', aktion: 'sp_ort_belege', titel: 'Ordner für verbuchte Belege', knoepfe_in_reihe: true,
        info: 'Der Ordner wird mit einer kleinen Prüfdatei geprüft. Klappt das nicht, bleibt es beim bisherigen Ordner.',
        felder: [{ typ: 'text', name: 'ordner_belege', label: 'Ordner', wert: String(AB.ordner_buchhaltung || AB.buchhaltung_standard || ''), platzhalter: String(AB.buchhaltung_standard || '/Dokumente/Buchhaltung'),
          pflicht: true, autocomplete: 'off' }],
        knoepfe: [{ text: 'Ordner prüfen und speichern', art: 'neben' }] });
      if (AB.art === 'webdav') ein.push({ typ: 'aktion', text: 'Wieder auf dem Server ablegen', aktion: 'sp_ort_server', frage: 'Neue Dateien wieder auf dem Server ablegen? Vorhandene Dateien bleiben am bisherigen Ort.' });
    }
    ort.push(...ein);
  }
  const opt = (Array.isArray(S.rollen) ? S.rollen : []).concat(Array.isArray(S.personen) ? S.personen : []).filter(o => /^(rolle|person):/.test(String(o.wert || '')));
  const inhaltR = [{ typ: 'tabelle', id: 'speicherort-rechte', titel: 'Wer Ordner teilen darf', spalten: [{ schluessel: 'wer', titel: 'Wer' }, { schluessel: 'seit', titel: 'Seit' },
      { schluessel: 'von', titel: 'Vergeben von' }, { schluessel: 'aktion', titel: 'Aktion' }],
    zeilen: R.map(x => ({ zellen: { wer: { text: String(x.name || ''), fett: true, neben: x.art === 'rolle' ? 'Rolle' : 'Person' }, seit: String(x.seit || ''), von: String(x.von || '–'),
      aktion: { aktion: { text: 'Entziehen', label: 'Entziehen: ' + String(x.name || ''), aktion: 'sp_recht_entziehen', werte: { id: String(x.id) },
        frage: 'Recht von ' + String(x.name || '') + ' entziehen? Bereits geteilte Ordner bleiben geteilt; nichts wird gelöscht.' } } } })),
    sortierung: {}, seite: 1, je_seite: 50, gesamt: R.length, leer: 'Bisher nur Admins.' }];
  if (EG.eingerichtet === true && opt.length) inhaltR.push({ typ: 'formular', id: 'speicherort-recht', aktion: 'sp_recht_neu', knoepfe_in_reihe: true,
    felder: [{ typ: 'auswahl', name: 'ziel', label: 'Rolle oder Person', wert: String(opt[0].wert), optionen: opt.map(o => ({ wert: String(o.wert), text: String(o.text || o.wert) })) }],
    knoepfe: [{ text: 'Recht vergeben', art: 'neben' }] });
  if (Number(S.freigaben) > 0) inhaltR.push({ typ: 'text', ton: 'grau', text: 'Mit Talents geteilte Ordner: ' + Number(S.freigaben) + '.' });
  abschnitte.push({ id: 'rechte', titel: 'Wer Ordner teilen darf', zahl: String(R.length), offen_standard: true,
    info: 'Admins dürfen das immer. Wer das Recht hat, gibt Ordner aus dem eigenen Speicherort für die eigenen Talents frei (Talent-Profil › Talent-Bereich). Welche Ordner das sind, legen diese Personen fest. Entziehen löscht keine Ordner und keine Inhalte.',
    inhalt: inhaltR });
  // BA9 (Migration 68): Download-Grenze für Talents (Dateien aus freigegebenen Ordnern lädt Ally über den Server)
  const TC = D.tc && D.tc.ok === true && D.tc.darf === true ? D.tc : null;
  if (TC) abschnitte.push({ id: 'downloads', titel: 'Downloads für Talents', zahl: String(TC.download_max_mb) + ' MB', offen_standard: false,
    info: 'Größte Datei, die ein Talent aus einem geteilten Ordner herunterladen kann. Ally holt die Datei dafür über den Server; sehr große Dateien belasten ihn. Größere Dateien sieht das Talent mit dem Hinweis „zu groß zum Herunterladen“.',
    inhalt: [{ typ: 'formular', id: 'download-max', aktion: 'sp_download_max', knoepfe_in_reihe: true,
      felder: [{ typ: 'zahl', name: 'max_mb', label: 'Höchstens je Datei (MB)', wert: String(TC.download_max_mb), min: 1, max: 1024, schritt: 1, pflicht: true }],
      knoepfe: [{ text: 'Speichern', art: 'neben' }] }] });
  return aus({ abschnitte });
}

// ---------- Postfächer ----------
if (bereich === 'postfaecher') {
  if (!PFR) return fehlt('Postfächer verwaltet eine Person mit dem Recht „Postfächer verwalten“.');
  const W = D.w || {};
  seite.beschreibung = 'Postfächer, zuständige Personen, Signatur und Einordnung.';
  const pfs = Array.isArray(W.postfaecher) ? W.postfaecher : [];
  const zugang = p => { const z = p.zugang || {}; return !z.eingerichtet ? { text: 'nicht eingerichtet', ton: 'grau', r: 2 } : (z.ergebnis && z.ergebnis !== 'ok') ? { text: 'Fehler', ton: 'warn', r: 1 } : { text: 'verbunden', ton: 'ok', r: 0 }; };
  const so = sortierung('postfaecher', ['adresse', 'name', 'platz', 'zugang', 'personen', 'status'], 'adresse');
  const wert = (p, sp) => sp === 'platz' ? Number(p.platz) || 0 : sp === 'zugang' ? zugang(p).r : sp === 'personen' ? (p.personen || []).length : sp === 'status' ? (p.aktiv ? 0 : 1) : String(p[sp] || '').toLowerCase();
  const liste = sortiere(pfs.slice(), so, wert);
  const bl = blatt('postfaecher', liste.length);
  const gew = pfs.find(p => p.adresse === P.postfach) || null;
