      felder: [{ typ: 'auswahl', name: 'standard_postfach', label: 'Standard-Postfach', wert: String(EI.standard_postfach || ''), optionen: [{ wert: '', text: 'keins' }].concat(pfs.map(p => ({ wert: p.adresse, text: String(p.adresse) }))), breite: 'voll' },
        { typ: 'text', name: 'absender_name', label: 'Absendername', wert: String(EI.absender_name || ''), pflicht: true }, { typ: 'text', name: 'signatur_name', label: 'Name in der Signatur', wert: String(EI.signatur_name || ''), pflicht: true }]
        .concat(hakenFelder), knoepfe: [{ text: 'Speichern', art: 'neben' }] }] });
    if (ADM) abschnitte.push({ id: 'fuer-alle', titel: 'Für alle', offen_standard: false, inhalt: [{ typ: 'formular', id: 'ki-hinweis-mail', aktion: 'ki_hinweis', werte: { art: 'mail' }, knoepfe_in_reihe: true,
      felder: [{ typ: 'haken', name: 'an', label: 'Hinweis „Erstellt mit KI-Unterstützung.“ in Mail-Entwürfen', an: (W.ki_hinweis || {}).mail === true }], knoepfe: [{ text: 'Speichern', art: 'neben' }] }] });
  } else if (bereich === 'marketing') {
