      felder: hakenFelder.concat([{ typ: 'auswahl', name: 'marketing_tag', label: 'Themenvorschläge am', wert: String(EI.marketing_tag || '1'), optionen: TAGE.map((t, i) => ({ wert: String(i + 1), text: t })) },
