        { typ: 'auswahl', name: 'marketing_anzahl', label: 'Anzahl der Vorschläge', wert: String(EI.marketing_anzahl || '3'), optionen: ['1', '2', '3', '4', '5'].map(n => ({ wert: n, text: n })) },
        { typ: 'auswahl', name: 'marketing_ansprache', label: 'Ansprache', wert: String(EI.marketing_ansprache || 'du'), optionen: [{ wert: 'du', text: 'Du' }, { wert: 'sie', text: 'Sie' }] },
        { typ: 'textbereich', name: 'marketing_themenfelder', label: 'Themenfelder', wert: String(EI.marketing_themenfelder || ''), zeilen: 3, breite: 'voll' },
