    if (ADM) abschnitte.push({ id: 'fuer-alle', titel: 'Für alle', offen_standard: false, inhalt: [{ typ: 'formular', id: 'ki-hinweis-marketing', aktion: 'ki_hinweis', werte: { art: 'marketing' }, knoepfe_in_reihe: true,
      felder: [{ typ: 'haken', name: 'an', label: 'Hinweis „Erstellt mit KI-Unterstützung.“ in Marketing-Texten', an: (W.ki_hinweis || {}).marketing === true }], knoepfe: [{ text: 'Speichern', art: 'neben' }] }] });
  } else if (hakenFelder.length) {
