  // Migration 181 (Koordinator 30.10.2026): die Hinweise zu Talents mit einer Zeile, die sagt, was man dort tut
  seite.beschreibung = bereich === 'talent-reports' ? 'Welche Hinweise zu deinen Talents Ally dir im Chat schickt.' : 'Einstellungen für ' + String(FN.name || '') + '.';
