// Parameter (ALLY 23, Einstellungen): Sitzung und Bereich (nur bekannte Bereiche, sonst Übersicht).
// BA10 Teil 2 (Migration 70): Code des Bestätigungslinks für die neue E-Mail-Adresse (em, nur 64 Hex-Zeichen) für ally_profil_ui.
const E = $input.first().json;
const P = E.parameter || {};
const B = ['profil', 'startseite', 'benachrichtigungen', 'kalender', 'unternehmen', 'team', 'postfaecher', 'regeln', 'ki', 'pakete'];
const b = String(P.bereich || '');
const bereich = B.includes(b) || /^[a-z0-9-]{1,40}$/.test(b) && b !== '' ? b : '';
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', bereich, /^[0-9a-f]{64}$/.test(String(P.em || '')) ? String(P.em) : ''] } }];

// Plan 51 / Migration 189 (Koordinator 31.10.2026): Buchungen ohne Preis zeigen „Kosten unbekannt“ statt 0 €; Summen mit einem unbekannten Teil zeigen den
// bekannten Betrag mit dem Zusatz „dazu N Aufrufe ohne Preis (Kosten unbekannt)“. ohne_preis/aufrufe kommen aus der Datenbank (Migration 189).
const KU_n = x => Math.max(0, Number((x || {}).ohne_preis) || 0);
const KU_alle = x => KU_n(x) > 0 && KU_n(x) >= (Number((x || {}).aufrufe) || 0);
const KU_t = n => n.toLocaleString('de-DE') + (n === 1 ? ' Aufruf' : ' Aufrufe') + ' ohne Preis';
const KU_dazu = n => 'dazu ' + KU_t(n) + ' (Kosten unbekannt)';
const KU_wert = (x, betrag) => KU_alle(x) ? 'Kosten unbekannt (' + KU_t(KU_n(x)) + ')' : KU_n(x) ? betrag + ' · ' + KU_dazu(KU_n(x)) : betrag;
// Konto und Design (ALLY 23, BA10 Teil 2, Migration 70, Stefan 20.10.2026): ergänzt die fertige Seitenbeschreibung, ohne „Seite beschreiben“ zu ändern.
// Profil: E-Mail-Adresse ändern (Bestätigungslink an die neue Adresse über das Absender-Postfach; ohne Absender-Postfach nur ein Hinweis) und Passwort ändern
// (Felder mit v2: der Browser schickt nur SHA-256 wie ALLY 8/ALLY 36). Unternehmen und Design: Logo, Bildmarke (wie ALLY 10). Marketing: Gestaltung der Grafiken und eigene
// Hintergründe (wie ALLY 8/ALLY 10), Veröffentlichen (LinkedIn, Instagram über die vorhandenen Abläufe, Seite „link“). Postfächer: Postfach-Zugang über den vorhandenen Ablauf.
// Superadmin-Inhalte (wie ALLY 8) seit 21.10.2026 nach Thema auf Pakete, KI und Budget, Team und Rollen, Plattform-Apps und Adressen verteilt (nur für Superadmins).
// Zugangsdaten werden nie angezeigt.
const aus = $input.all().map(x => x.json);
const D = $('Daten laden').first().json || {};
const E = $('Start').first().json;
const P = E.parameter || {};
const bereich = String(P.bereich || '');
const ADM = D.admin === true, SA = D.superadmin === true;
const W = D.w || {};
const ziel = (b, extra, anker) => ({ seite: 'einstellungen', parameter: Object.assign(b ? { bereich: b } : {}, extra || {}), anker });
const verbindung = (art, id) => ({ seite: 'link', parameter: Object.assign({ art }, id ? { id } : {}) });
const zahl = (v, n) => v === null || v === undefined || v === '' || !isFinite(Number(v)) ? '–' : Number(v).toLocaleString('de-DE', { minimumFractionDigits: n, maximumFractionDigits: n });
const gebucht = k => (Array.isArray(W.pakete) ? W.pakete : []).some(p => p && p.schluessel === k && p.gebucht === true);
const CDN = { logo_fuer_dunkel: 'Logo für dunkle Flächen', logo_fuer_hell: 'Logo für helle Flächen', bildmarke_fuer_dunkel: 'Bildmarke für dunkle Flächen', bildmarke_fuer_hell: 'Bildmarke für helle Flächen' };
const groesse = n => Number(n) > 0 ? (Number(n) >= 1048576 ? zahl(Number(n) / 1048576, 1) + ' MB' : zahl(Math.max(1, Math.round(Number(n) / 1024)), 0) + ' KB') : '';
// Sortierung je Tabelle wie in „Seite beschreiben“ (Zustand je Person, Schlüssel einstellungen.<tabelle>)
const ZU = D.zustand || {};
const sortierung = (tab, erlaubt, std, r0) => { const s = (ZU['einstellungen.' + tab] || {}).sortierung || {};
  return { spalte: erlaubt.includes(s.spalte) ? s.spalte : std, richtung: s.richtung === 'ab' || s.richtung === 'auf' ? s.richtung : (r0 || 'auf') }; };
const sortiere = (liste, so, wert) => liste.map((z, i) => [z, i]).sort((a, b) => { const x = wert(a[0], so.spalte), y = wert(b[0], so.spalte);
  const c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x ?? '').localeCompare(String(y ?? ''), 'de', { numeric: true }); return (so.richtung === 'ab' ? -c : c) || a[1] - b[1]; }).map(x => x[0]);
const src = v => /^data:image\/(svg\+xml|png|jpeg);base64,[A-Za-z0-9+/]+={0,2}$/.test(String(v || '')) ? String(v) : '';

for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object') continue;
  const AB = Array.isArray(I.abschnitte) ? I.abschnitte : null;
  const nach = (id, neu) => { const i = AB.findIndex(a => a && a.id === id); AB.splice(i < 0 ? AB.length : i + 1, 0, ...neu); };

  // ---------- Profil: E-Mail-Adresse und Passwort ----------
  if (bereich === 'profil' && AB && D.pk && D.pk.ok === true && !AB.some(a => a && a.id === 'anmeldung')) {
    const K = D.pk, O = K.offen && typeof K.offen === 'object' ? K.offen : null, BE = K.bestaetigen && typeof K.bestaetigen === 'object' ? K.bestaetigen : null;
    const code = /^[0-9a-f]{64}$/.test(String(P.em || '')) ? String(P.em) : '';
    if (BE && code) {
