        ? [{ typ: 'paare', eintraege: [{ label: 'Neue E-Mail-Adresse', wert: String(BE.neue_email || '') }, { label: 'Bisher', wert: String(K.email || '–') }] },
           { typ: 'formular', id: 'email-bestaetigen', aktion: 'profil_email_bestaetigen', werte: { code }, zurueck_ziel: ziel('profil', {}, 'a-anmeldung'),
             info: 'Nach dem Bestätigen gilt die neue Adresse für die Anmeldung. Das Passwort bleibt gleich.', knoepfe: [{ text: 'E-Mail-Adresse bestätigen' }] }]
        : [{ typ: 'text', ton: 'warn', text: BE.grund === 'abgelaufen' ? 'Dieser Bestätigungslink ist abgelaufen oder wurde schon benutzt. Die Änderung lässt sich unten neu anfordern.'
            : 'Dieser Bestätigungslink gehört nicht zu deiner Anmeldung. Die E-Mail-Adresse bleibt unverändert.' }] });
    }
    const VS = { wartet: 'wird gesendet', in_arbeit: 'wird gesendet', gesendet: 'gesendet', fehler: 'konnte nicht gesendet werden', verfallen: 'nicht gesendet', unklar: 'unklar' };
    const inhalt = [{ typ: 'paare', eintraege: [{ label: 'E-Mail-Adresse für die Anmeldung', wert: String(K.email || '–') }]
      .concat(O ? [{ label: 'Neue Adresse (wartet auf Bestätigung)', wert: String(O.neue_email || '') }, { label: 'Link gültig bis', wert: String(O.bis || '–') },
        { label: 'Bestätigungsmail', wert: VS[O.versand] || '–' }] : []) }];
    if (O) inhalt.push({ typ: 'aktion', text: 'Änderung verwerfen', aktion: 'profil_email_verwerfen', frage: 'Änderung der E-Mail-Adresse verwerfen? Der Bestätigungslink gilt danach nicht mehr.' });
    inhalt.push({ typ: 'unterueberschrift', text: 'E-Mail-Adresse ändern',
      info: 'Ally schickt einen Bestätigungslink an die neue Adresse. Erst nach dem Bestätigen (mit deiner bisherigen Anmeldung) gilt sie für die Anmeldung.' });
    if (K.versand_aktiv !== true) inhalt.push({ typ: 'text', ton: 'grau', text: 'Zum Ändern der E-Mail-Adresse braucht Ally ein Absender-Postfach für Systemnachrichten. Es wird unter Einstellungen › Gemeinsame Postfächer eingerichtet (Admin). Bis dahin bleibt die E-Mail-Adresse unverändert.' });
    else inhalt.push({ typ: 'formular', id: 'email-aendern', aktion: 'profil_email', spalten: 2, felder: [
        { typ: 'email', name: 'email', label: 'Neue E-Mail-Adresse', pflicht: true, autocomplete: 'email' },
        { typ: 'passwort', v2: true, name: 'alt', label: 'Bisheriges Passwort', pflicht: true, autocomplete: 'current-password' }],
      knoepfe: [{ text: 'Bestätigungslink senden', art: 'neben' }] });
    inhalt.push({ typ: 'unterueberschrift', text: 'Passwort ändern', info: 'Das Passwort verlässt den Browser nicht im Klartext. Nach dem Ändern werden andere Anmeldungen beendet.' },
      { typ: 'formular', id: 'passwort-aendern', aktion: 'profil_passwort', spalten: 2, frage: 'Passwort jetzt ändern? Andere Anmeldungen werden dabei beendet.', felder: [
        { typ: 'passwort', v2: true, name: 'alt', label: 'Bisheriges Passwort', pflicht: true, autocomplete: 'current-password', breite: 'voll' },
        { typ: 'passwort', v2: true, name: 'neu', label: 'Neues Passwort', pflicht: true, autocomplete: 'new-password', mind: 10, laenge: true, info: 'Mindestens 10 Zeichen' },
        { typ: 'passwort', v2: true, name: 'wiederholung', label: 'Neues Passwort wiederholen', pflicht: true, autocomplete: 'new-password', gleich: 'neu' }],
      knoepfe: [{ text: 'Passwort ändern', art: 'neben' }] });
    nach('profil', [{ id: 'anmeldung', titel: 'E-Mail-Adresse und Passwort', zahl: O ? 'Bestätigung offen' : '', offen_standard: !!O || !!code, inhalt }]);
  }

  // ---------- Unternehmen und Design: Logo und Bildmarke (wie ALLY 10) ----------
  if (bereich === 'unternehmen' && ADM && Array.isArray(I.fenster)) {
    const UN = Array.isArray(W.unternehmen) ? W.unternehmen : [];
    const gew = UN.find(u => String(u.id) === String(P.unternehmen || '')) || null;
    const fe = I.fenster.find(f => f && f.id === 'unternehmen');
    if (gew && fe && Array.isArray(fe.inhalt) && !fe.inhalt.some(b => b && b.id === 'cd-datei')) {
      const cd = gew.cd || {}, DT = cd.dateien || {}, FB = cd.farben || {};
      const dunkel = /^#[0-9A-Fa-f]{6}$/.test(String(FB.farbe_dunkel || '')) ? String(FB.farbe_dunkel) : '';
      const teil = [{ typ: 'unterueberschrift', text: 'Logo und Bildmarke', info: 'SVG oder PNG, höchstens 500 KB. Das Logo für helle Flächen ist freiwillig; die anderen lassen sich nur ersetzen. Ohne gespeicherte Schrift und Farben gelten beim Hochladen die Standardwerte.' }];
      // Fehler Nr. 19 (Stefan 02.11.2026, 08:30): Hochladen immer möglich; ohne Schrift und Farben speichert die Datenbank dabei die Standardwerte (Migration 198)
      {
        teil.push({ typ: 'bilder', eintraege: Object.keys(CDN).map(k => { const x = DT[k] || null;
          return { titel: CDN[k], src: x ? src(x.src) : '', alt: CDN[k], grund: /dunkel/.test(k) ? 'dunkel' : 'hell', farbe: dunkel, leer: 'noch keine Datei',
            neben: x ? [String(x.dateiname || ''), groesse(x.groesse), x.geaendert ? String(x.geaendert) : ''].filter(Boolean).join(' · ') : '' }; }) });
        teil.push({ typ: 'formular', id: 'cd-datei', aktion: 'cd_datei', datei: true, werte: { id: String(gew.id) }, spalten: 2, felder: [
          { typ: 'auswahl', name: 'art', label: 'Datei', wert: 'logo_fuer_dunkel', optionen: Object.keys(CDN).map(k => ({ wert: k, text: CDN[k] })) },
          { typ: 'datei', name: 'datei', label: 'SVG oder PNG', pflicht: true, accept: '.svg,.png,image/svg+xml,image/png' }], knoepfe: [{ text: 'Hochladen', art: 'neben' }] });
        if (DT.logo_fuer_hell) teil.push({ typ: 'aktion', text: 'Logo für helle Flächen entfernen', aktion: 'cd_datei_loeschen', werte: { id: String(gew.id), art: 'logo_fuer_hell' },
          frage: 'Logo für helle Flächen entfernen? Dann gilt dort das Logo für dunkle Flächen.' });
      }
      const i = fe.inhalt.findIndex(b => b && b.id === 'cd');
      fe.inhalt.splice(i < 0 ? fe.inhalt.length : i + 1, 0, ...teil);
    }
  }

  // ---------- Marketing: Veröffentlichen, Gestaltung der Grafiken und Hintergründe ----------
  if (bereich === 'marketing' && AB && !AB.some(a => a && a.id === 'veroeffentlichen')) {
    const neu = [];
    if (gebucht('marketing_posten') && D.li && typeof D.li === 'object') {
      const L = D.li, IG = W.instagram || {};
      const li = L.verbunden ? (L.abgelaufen ? 'abgelaufen' : 'verbunden') + (L.name ? ' als ' + String(L.name) : '') + (L.bis ? ' (bis ' + String(L.bis) + ')' : '') : 'nicht verbunden';
      const inhalt = [{ typ: 'paare', eintraege: [{ label: 'Dein LinkedIn-Profil', wert: li },
        { label: 'LinkedIn-Unternehmensseite', wert: L.seite_verbunden ? (L.seite_abgelaufen ? 'abgelaufen' : 'verbunden') + (L.seite_name ? ' (' + String(L.seite_name) + ')' : '') : 'nicht verbunden' },
        { label: 'Instagram', wert: IG.konto ? 'verbunden als ' + String(IG.konto) + (IG.seit ? ' seit ' + String(IG.seit) : '') : 'nicht verbunden' }] }];
      if (L.app) inhalt.push({ typ: 'aktion', text: L.verbunden ? 'LinkedIn neu verbinden' : 'Mit LinkedIn verbinden', ziel: verbindung('li') });
      else inhalt.push({ typ: 'text', ton: 'grau', text: 'LinkedIn ist noch nicht eingerichtet (LinkedIn-App, Admin).' });
      if (ADM && L.seite_app) inhalt.push({ typ: 'aktion', text: L.seite_verbunden ? 'Unternehmensseite neu verbinden' : 'LinkedIn-Unternehmensseite verbinden', ziel: verbindung('lis') });
      inhalt.push({ typ: 'aktion', text: 'Instagram und LinkedIn verwalten', ziel: verbindung('ig') });
      neu.push({ id: 'veroeffentlichen', titel: 'Veröffentlichen', offen_standard: false, inhalt,
        info: 'Verbinden, Trennen und die App-Daten laufen über die vorhandenen Abläufe und öffnen die bisherige Oberfläche. Zugangsdaten werden hier nicht angezeigt.' });
    }
    if (ADM && gebucht('marketing')) {
      for (const u of (Array.isArray(W.unternehmen) ? W.unternehmen : [])) {
        const cd = u.cd || {};
        if (cd.vorhanden !== true) continue;
        const G = cd.gestaltung || {}, ST = Array.isArray(G.stile) ? G.stile : [], HG = Array.isArray(cd.hintergruende) ? cd.hintergruende : [];
        const FB = cd.farben || {}, dunkel = /^#[0-9A-Fa-f]{6}$/.test(String(FB.farbe_dunkel || '')) ? String(FB.farbe_dunkel) : '';
        const inhalt = [{ typ: 'formular', id: 'gestaltung-' + u.id, aktion: 'cd_gestaltung', werte: { id: String(u.id) }, spalten: 2, felder: [
          { typ: 'haken', name: 'stil__dunkel', label: 'Folien dunkel', an: ST.includes('dunkel') }, { typ: 'haken', name: 'stil__hell', label: 'Folien hell', an: ST.includes('hell') },
          { typ: 'haken', name: 'stil__akzent', label: 'Folien in der Akzentfarbe', an: ST.includes('akzent') }, { typ: 'haken', name: 'punkte', label: 'Punktraster', an: G.punkte !== false },
          { typ: 'haken', name: 'boegen', label: 'Bögen', an: G.boegen !== false }, { typ: 'haken', name: 'gross_icon', label: 'Großes Icon', an: G.gross_icon !== false },
          { typ: 'haken', name: 'icons', label: 'Icons im Inhalt', an: G.icons !== false }],
          info: 'Mindestens ein Folienstil. Einzelne Icons abwählen geht in der bisherigen Oberfläche.', knoepfe: [{ text: 'Speichern', art: 'neben' }] },
          { typ: 'unterueberschrift', text: 'Eigene Hintergründe', info: 'JPG oder PNG, höchstens 1 MB, bis zu 6 Bilder. Hell oder dunkel bestimmt die Schriftfarbe darauf.' },
          { typ: 'bilder', eintraege: HG.map(h => ({ titel: String(h.dateiname || 'Hintergrund'), src: src(h.vorschau), alt: String(h.dateiname || 'Hintergrund'), grund: h.hell ? 'hell' : 'dunkel',
            farbe: dunkel, leer: 'keine Vorschau', neben: [h.hell ? 'hell' : 'dunkel', groesse(h.groesse), h.angelegt ? String(h.angelegt) : ''].filter(Boolean).join(' · ') })) }];
        if (!HG.length) inhalt.pop();
        for (const h of HG) inhalt.push({ typ: 'aktion', text: 'Entfernen: ' + String(h.dateiname || 'Hintergrund'), aktion: 'hintergrund_loeschen', werte: { id: String(u.id), bild: String(h.id) },
          frage: 'Hintergrund „' + String(h.dateiname || '') + '“ entfernen?' });
        if (HG.length < 6) inhalt.push({ typ: 'formular', id: 'hintergrund-' + u.id, aktion: 'cd_datei', datei: true, werte: { id: String(u.id), art: 'hintergrund' }, spalten: 2, felder: [
          { typ: 'datei', name: 'datei', label: 'Bild (JPG oder PNG)', pflicht: true, accept: '.jpg,.jpeg,.png,image/jpeg,image/png' },
          { typ: 'auswahl', name: 'helligkeit', label: 'Das Bild ist', wert: 'dunkel', optionen: [{ wert: 'dunkel', text: 'dunkel' }, { wert: 'hell', text: 'hell' }] }],
          knoepfe: [{ text: 'Hochladen', art: 'neben' }] });
        neu.push({ id: 'gestaltung-' + u.id, titel: 'Gestaltung der Grafiken: ' + String(u.name || ''), zahl: HG.length ? HG.length + ' Hintergr.' : '', offen_standard: false, inhalt });
      }
    }
    if (neu.length) { const i = AB.findIndex(a => a && a.id === 'funktion'); AB.splice(i < 0 ? AB.length : i, 0, ...neu); }
  }

  // ---------- Postfächer: Postfach-Zugang über den vorhandenen Ablauf ----------
  if (bereich === 'postfaecher' && AB && ADM && !AB.some(a => a && a.id === 'zugang')) {
    AB.splice(Math.min(1, AB.length), 0, { id: 'zugang', titel: 'Postfach-Zugang', offen_standard: false,
      info: 'Zugangsdaten (IMAP) werden in der bisherigen Oberfläche eingegeben und dort geprüft. Ally zeigt sie nie an.',
      inhalt: [{ typ: 'text', text: 'Postfach verbinden, Zugang ändern oder ein Postfach entfernen.' }, { typ: 'aktion', text: 'Postfach-Zugang einrichten', ziel: verbindung('pf') }] });
  }

  // ---------- Superadmin-Inhalte nach Thema (Stefan 21.10.2026, 09:32/09:33): keine eigene Seite „Superadmin“ mehr. Vertrag und Produkt unter Pakete,
  // Preise, Modelle und echte Kosten unter KI und Budget, Admin- und Superadmin-Recht unter Team und Rollen, Plattform-Apps und Adressen als eigene Seiten unter Administration.
  // Nur für Superadmins: Daten lädt die Datenbank nur für sie (sa, sam, mr, oa); für alle anderen gibt es diese Abschnitte und Seiten nicht (Seiten = unbekannter Bereich).
  // Kennzeichen für Superadmins: schloss: true (Schloss-Symbol im Baukasten) und i-Info „Nur für Superadmins sichtbar.“
  const S = SA && D.sa && D.sa.ok === true ? D.sa : null;
  const NUR = 'Nur für Superadmins sichtbar.';
  const mitNur = x => [NUR].concat(Array.isArray(x) ? x : x ? [x] : []);
  const opt = (w, t) => ({ wert: w, text: t });
  if (S && AB && bereich === 'pakete') {
    const V = S.vertrag || {};
    const leer = v => v === null || v === undefined ? '' : String(v);
    nach('pakete', [{ id: 'vertrag', titel: 'Vertrag', offen_standard: false, schloss: true, info: mitNur('Das KI-Budget steht unter KI und Budget.'), inhalt: [
      { typ: 'paare', eintraege: [{ label: 'Aktive Personen', wert: String(S.personen_aktiv ?? '–') }, { label: 'Zuletzt geändert', wert: [V.geaendert_am, V.geaendert_von].filter(Boolean).join(' · ') || '–' }] },
      { typ: 'formular', id: 'sa-vertrag', aktion: 'sa_vertrag', spalten: 2,
        werte: { ki_budget_eur: leer(V.ki_budget_eur).replace('.', ','), budget_modus: leer(V.budget_modus), warn_prozent: leer(V.warn_prozent), spar_prozent: leer(V.spar_prozent) },
        felder: [
        { typ: 'text', name: 'paket', label: 'Paketname', wert: String(V.paket || ''), pflicht: true }],
        knoepfe: [{ text: 'Vertrag speichern', art: 'neben' }] }] },
      { id: 'produkt', titel: 'Produkt', offen_standard: false, schloss: true, info: mitNur('Name des Assistenten, wie ihn alle sehen, und Name des Anbieters.'), inhalt: [{ typ: 'formular', id: 'sa-produkt', aktion: 'sa_produkt', spalten: 2, felder: [
        { typ: 'text', name: 'produkt_name', label: 'Produktname', wert: String(S.produkt_name || ''), pflicht: true },
        { typ: 'text', name: 'anbieter_name', label: 'Anbieter', wert: String(S.anbieter_name || '') }], knoepfe: [{ text: 'Speichern', art: 'neben' }] }] }]);
    // vorhandene Superadmin-Teile der Seite (Pakete im Vertrag, Ein-/Ausschalten der Funktionen) kennzeichnen
    for (const a of AB) for (const b of (a && Array.isArray(a.inhalt) ? a.inhalt : [])) if (b && b.typ === 'formular' && b.id === 'module') { b.schloss = true; b.info = mitNur(b.info); }
  }
  if (S && AB && bereich === 'ki') {
    const V = S.vertrag || {}, MN = S.monat || {}, AN = String(S.anbieter_name || '');
    for (const a of AB) for (const b of (a && Array.isArray(a.inhalt) ? a.inhalt : [])) if (b && b.typ === 'formular' && b.id === 'budget') { b.titel = b.titel || 'Budget ändern'; b.schloss = true; b.info = mitNur(b.info); }
    const neu = [];
    neu.push({ id: 'sa-preise', titel: 'Preise und eigener Schlüssel', offen_standard: false, schloss: true, info: mitNur('Die Quelle des Schlüssels stellst du im Abschnitt KI-Zugang ein.'), inhalt: [
      { typ: 'paare', eintraege: [{ label: 'Zugangsdaten in n8n', wert: S.ki_zugangsdaten_eingerichtet === true ? 'eingerichtet' : 'nicht eingerichtet' },
        { label: 'Schlüssel von', wert: V.ki_schluessel === 'kunde' ? 'Kundschaft' : 'Anbieter' + (AN ? ' (' + AN + ')' : '') }] },
      { typ: 'formular', id: 'sa-ki', aktion: 'sa_ki', spalten: 2, felder: [
        { typ: 'text', name: 'preis_faktor', label: 'Preisfaktor', wert: V.preis_faktor === null || V.preis_faktor === undefined ? '' : String(V.preis_faktor).replace('.', ','), pflicht: true,
          info: 'Preis für Kundschaft = Listenpreis × Preisfaktor; gilt nur mit dem Schlüssel des Anbieters.' },
        { typ: 'haken', name: 'eigener_schluessel_erlaubt', label: 'Kundschaft darf einen eigenen Anthropic-Schlüssel nutzen', an: V.eigener_schluessel_erlaubt === true, breite: 'voll' }],
        knoepfe: [{ text: 'Speichern', art: 'neben' }] }] });
    const ML = Array.isArray(S.modelle) ? S.modelle : [];
    const EIN = { einfach: 'einfache Aufgaben', anspruchsvoll: 'anspruchsvolle Aufgaben', beide: 'beide Aufgabenarten' };
    const soM = sortierung('sa-modelle', ['name', 'liste', 'kunde', 'frei'], 'name');
    const wertM = (m, sp) => sp === 'liste' ? Number((m.liste_usd || {}).eingabe) || 0 : sp === 'kunde' ? Number((m.kunde_eur || {}).eingabe) || 0 : sp === 'frei' ? (m.freigegeben ? 0 : 1) : String(m.name || m.modell || '').toLowerCase();
    const preis = (x, z) => x && typeof x === 'object' ? zahl(x.eingabe, 2) + ' / ' + zahl(x.ausgabe, 2) + ' ' + z : '–';
    neu.push({ id: 'sa-modelle', titel: 'Modelle und Preise', zahl: String(ML.length), offen_standard: false, schloss: true, info: mitNur('Preise je 1 Million Tokens, Eingabe / Ausgabe. Freigeschaltete Modelle stehen im Abschnitt Modelle zur Wahl.'),
      inhalt: [{ typ: 'tabelle', id: 'sa-modelle', titel: 'Modelle', spalten: [{ schluessel: 'name', titel: 'Modell', sortierbar: true }, { schluessel: 'liste', titel: 'Listenpreis', ausrichtung: 'rechts', sortierbar: true },
        { schluessel: 'kunde', titel: 'Preis für Kundschaft', ausrichtung: 'rechts', sortierbar: true }, { schluessel: 'frei', titel: 'Freigeschaltet', sortierbar: true }],
        sortierung: soM, zeilen: sortiere(ML, soM, wertM).map(m => ({ zellen: { name: { text: String(m.name || m.modell || ''), fett: true, neben: [m.modell, m.eingestellt ? 'eingestellt für ' + (EIN[m.eingestellt] || m.eingestellt) : '', m.stand ? 'Preisstand ' + m.stand : ''].filter(Boolean).join(' · ') },
          liste: preis(m.liste_usd, '$'), kunde: preis(m.kunde_eur, '€'),
          frei: { aktion: { text: m.freigegeben ? 'Freigeschaltet – sperren' : 'Gesperrt – freischalten', aktion: 'sa_modell_freigabe', werte: { modell: String(m.modell || ''), freigegeben: m.freigegeben ? '' : '1' },
            frage: (m.freigegeben ? 'Freischaltung aufheben: ' : 'Freischalten: ') + String(m.name || m.modell || '') + '?' } } } })),
        seite: 1, je_seite: Math.max(20, ML.length), gesamt: ML.length, leer: 'Keine Modelle in der Preisliste.' }] });
    const kurs = isFinite(Number(MN.kurs)) && MN.kurs !== null ? Number(MN.kurs) : null;
    const betrag = (usd, eur) => zahl(usd || 0, 2) + ' $' + (eur !== null && eur !== undefined ? ' · ' + zahl(eur, 2) + ' €' : kurs ? ' · ' + zahl(Number(usd || 0) * kurs, 2) + ' €' : '');
    const FN = Array.isArray(MN.funktionen) ? MN.funktionen : [], MD = Array.isArray(MN.modelle) ? MN.modelle : [];
    const soF = sortierung('sa-monat-funktionen', ['n', 'a', 'k', 'p', 'e'], 'k', 'ab'), soD = sortierung('sa-monat-modelle', ['n', 'a', 'k', 'p'], 'k', 'ab');
    const wertMo = (x, sp) => sp === 'n' ? String(x.name || x.funktion || x.modell || '').toLowerCase() : sp === 'a' ? Number(x.aufrufe) || 0 : sp === 'p' ? Number(x.kunde_usd) || 0 : sp === 'e' ? Number(x.eigener_schluessel_usd) || 0 : Number(x.kosten_usd) || 0;
    neu.push({ id: 'sa-monat', titel: 'Echte Kosten im Monat', offen_standard: false, schloss: true, info: mitNur('Echte Kosten = Listenpreis von Anthropic für Aufrufe mit dem Schlüssel des Anbieters. Aufrufe mit dem eigenen Schlüssel der Kundschaft zahlt die Kundschaft direkt.'
        + (kurs ? ' Euro mit dem Referenzkurs der EZB: 1 $ = ' + zahl(kurs, 4) + ' €.' : '')),
      inhalt: [{ typ: 'paare', eintraege: [{ label: 'Echte Kosten', wert: KU_wert(MN, betrag(MN.kosten_usd, MN.kosten_eur)) }, { label: 'Preis für Kundschaft', wert: KU_wert(MN, betrag(MN.kunde_usd, MN.kunde_eur)) },
        { label: 'Anteil', wert: betrag(MN.anteil_usd, MN.anteil_eur) }, { label: 'Mit eigenem Schlüssel der Kundschaft', wert: betrag(MN.eigener_schluessel_usd, MN.eigener_schluessel_eur) },
        { label: 'Aufrufe', wert: zahl(MN.aufrufe || 0, 0) }].concat(Number(MN.ohne_preis) > 0 ? [{ label: 'Aufrufe ohne Preis', wert: zahl(MN.ohne_preis, 0) }] : []) },
        { typ: 'tabelle', id: 'sa-monat-funktionen', titel: 'Je Funktion', spalten: [{ schluessel: 'n', titel: 'Funktion', sortierbar: true }, { schluessel: 'a', titel: 'Aufrufe', ausrichtung: 'rechts', sortierbar: true },
          { schluessel: 'k', titel: 'Echte Kosten', ausrichtung: 'rechts', sortierbar: true }, { schluessel: 'p', titel: 'Preis für Kundschaft', ausrichtung: 'rechts', sortierbar: true }, { schluessel: 'e', titel: 'Eigener Schlüssel', ausrichtung: 'rechts', sortierbar: true }],
          sortierung: soF, zeilen: sortiere(FN, soF, wertMo).map(f => ({ zellen: { n: String(f.name || f.funktion || ''), a: zahl(f.aufrufe || 0, 0) + (KU_n(f) ? ' (' + zahl(KU_n(f), 0) + ' ohne Preis)' : ''), k: KU_alle(f) ? 'Kosten unbekannt' : betrag(f.kosten_usd),
            p: KU_alle(f) ? 'Kosten unbekannt' : betrag(f.kunde_usd), e: betrag(f.eigener_schluessel_usd) } })),
          seite: 1, je_seite: Math.max(20, FN.length), gesamt: FN.length, leer: 'In diesem Monat noch keine KI-Aufrufe.' },
        { typ: 'tabelle', id: 'sa-monat-modelle', titel: 'Je Modell', spalten: [{ schluessel: 'n', titel: 'Modell', sortierbar: true }, { schluessel: 'a', titel: 'Aufrufe', ausrichtung: 'rechts', sortierbar: true },
          { schluessel: 'k', titel: 'Listenpreis', ausrichtung: 'rechts', sortierbar: true }, { schluessel: 'p', titel: 'Preis für Kundschaft', ausrichtung: 'rechts', sortierbar: true }],
          sortierung: soD, zeilen: sortiere(MD, soD, wertMo).map(m => ({ zellen: { n: String(m.name || m.modell || ''), a: zahl(m.aufrufe || 0, 0) + (KU_n(m) ? ' (' + zahl(KU_n(m), 0) + ' ohne Preis)' : ''), k: KU_alle(m) ? 'Kosten unbekannt' : betrag(m.kosten_usd),
            p: KU_alle(m) ? 'Kosten unbekannt' : betrag(m.kunde_usd) } })),
          seite: 1, je_seite: Math.max(20, MD.length), gesamt: MD.length, leer: 'In diesem Monat noch keine KI-Aufrufe.' }] });
    AB.push(...neu);
  }
  if (S && AB && bereich === 'team') {
    const PE = Array.isArray(S.personen) ? S.personen : [];
    const soP = sortierung('sa-personen', ['name', 'admin', 'sa'], 'name');
    const schalter = (p, recht, an) => p.ich && recht === 'admin' && an ? 'Admin (eigenes Recht)' : { aktion: { text: an ? 'ja – entziehen' : 'nein – vergeben', ok_text: an ? 'Recht entziehen' : 'Recht vergeben', aktion: 'sa_person_' + recht,   // A–Z Punkt 11: benannter Knopf in der Rückfrage
      werte: Object.assign({ id: String(p.id || '') }, { [recht]: an ? '' : '1' }), frage: (an ? 'Recht ' : 'Recht ') + (recht === 'admin' ? 'Admin' : 'Superadmin') + (an ? ' entziehen: ' : ' vergeben: ') + String(p.name || '') + '?' } };
    nach('personen', [{ id: 'sa-personen', titel: 'Admin und Superadmin', zahl: String(PE.length), offen_standard: false, schloss: true, info: mitNur('Admins haben alle Rechte außer Superadmin, Superadmins haben alle Rechte.'),
      inhalt: [{ typ: 'tabelle', id: 'sa-personen', titel: 'Personen', spalten: [{ schluessel: 'name', titel: 'Person', sortierbar: true }, { schluessel: 'admin', titel: 'Admin', sortierbar: true }, { schluessel: 'sa', titel: 'Superadmin', sortierbar: true }],
        sortierung: soP, zeilen: sortiere(PE, soP, (p, sp) => sp === 'admin' ? (p.admin ? 0 : 1) : sp === 'sa' ? (p.superadmin ? 0 : 1) : String(p.name || '').toLowerCase()).map(p => ({ zellen: { name: { text: String(p.name || '') + (p.ich ? ' (du)' : ''), fett: true, neben: [p.aktiv === false ? 'deaktiviert' : '', String(p.id || '')].filter(Boolean).join(' · ') },
          admin: schalter(p, 'admin', p.admin === true), sa: schalter(p, 'superadmin', p.superadmin === true) } })),
        seite: 1, je_seite: Math.max(20, PE.length), gesamt: PE.length, leer: 'Keine Personen.' }] }]);
  }
  // Eigene Seiten unter Administration (nur Superadmin): Plattform-Apps (Abschnitte ergänzt „Zugänge und Apps“), Adressen (ergänzt „Adresse der Oberfläche“)
  if (SA && (bereich === 'plattform-apps' || bereich === 'adressen')) {
    const titel = bereich === 'adressen' ? 'Adressen' : 'Plattform-Apps';
    const seite = Object.assign({}, I.seite || {}, { titel, beschreibung: bereich === 'adressen' ? 'Adresse der Oberfläche.' : 'Meta-App, Apps der weiteren Plattformen, Datenlöschung und Rechtstexte.',
      krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: 'Einstellungen', ziel: { seite: 'einstellungen' } }, { text: titel }] });
    j.inhalt = { seite, abschnitte: [] };
  }
}
return aus.map(json => ({ json }));

