// - Postfächer: Postfach-Zugang je Platz (pf_zugang_pruefen, pf_zugang_speichern, pf_platz_freigeben → ALLY 9), neues Postfach auf einem freien Platz.
//   (instagram, Schlüsseltausch wie ALLY 8); Gestaltung der Grafiken: einzelne Icons abwählen (cd_gestaltung mit icons_liste wie ALLY 8).
// - Talents: KI-Funktionen (kf_speichern) und Speicherort der Talents-Dateien (ab_*), wie ALLY 8 (Einstellungen › Talents › KI-Funktionen, Speicherort).
const aus = $('Konto und Design').all().map(x => x.json);
const Z = $input.first().json || {};
const D = $('Daten laden').first().json || {};
const E = $('Start').first().json;
const P = E.parameter || {};
const bereich = String(P.bereich || '');
const ADM = D.admin === true, SA = D.superadmin === true, PFR = D.postfaecher_recht === true;
const W = D.w || {};
const LI = x => Array.isArray(x) ? x : [];
const opt = (w, t) => ({ wert: String(w ?? ''), text: String(t ?? '') });
const ziel = (b, extra, anker) => ({ seite: 'einstellungen', parameter: Object.assign(b ? { bereich: b } : {}, extra || {}), anker });
const verbindung = (art, id) => ({ seite: 'link', parameter: Object.assign({ art }, id ? { id } : {}) });
const KEIN_ZEIGEN = 'Wird nur gespeichert und nie angezeigt.';
const geheimFeld = (name, label, vorhanden, pflicht) => ({ typ: 'passwort', name, label, autocomplete: 'new-password', pflicht: !!pflicht && !vorhanden,
  platzhalter: vorhanden ? 'hinterlegt, leer lassen = unverändert' : '', info: (vorhanden ? 'Hinterlegt. ' : '') + KEIN_ZEIGEN });
// Anleitungen je Plattform: Text unverändert aus ALLY 8 („Plattform-Apps und Speicherort einsetzen“, Stand 18.10.2026), hier als i-Symbol
const ANLEITUNG = {
  facebook: ['Im Meta App Dashboard die bestehende Meta-App öffnen (die App für „Instagram über Facebook“), keine neue App.',
    'Berechtigung read_insights hinzufügen (hängt von pages_read_engagement und pages_show_list ab). Ob der Anwendungsfall dort angeboten wird: nicht geprüft.',
    'Die Weiterleitungs-URI oben bei Facebook Login unter „Valid OAuth Redirect URIs“ eintragen, genau so.',
    'Im Entwicklungsmodus können sich nur Personen mit Rolle in der App verbinden; für fremde Seiten braucht read_insights eine Freigabe im App Review.',
    'Seiten-Statistiken gibt es erst ab 100 Likes; die Person braucht auf der Seite die Aufgabe „Statistiken ansehen“.',
    'Hier den Schalter einschalten und speichern. App-ID und Geheimcode kommen aus der Karte Meta-App.'],
  threads: ['Meta-App mit dem Anwendungsfall „Access the Threads API“ anlegen (nicht kombinierbar mit Facebook Login).',
    'Unter Settings stehen Threads app ID und Threads app secret (nicht die normale Meta-App-ID).',
    'Unter Settings › Client OAuth Settings die Weiterleitungs-URI oben eintragen und speichern. Das Dashboard hängt eventuell einen Schrägstrich an – prüfen.',
    'Berechtigungen threads_basic und threads_manage_insights hinzufügen.',
    'Testkonten: „Add or Remove Threads Test Users“, Rolle Threads Testers; das Konto nimmt die Einladung in den Threads-Einstellungen an.',
    'Für fremde Konten: App Review je Berechtigung und App veröffentlichen.',
    'Hier Threads-App-ID und Geheimcode eintragen.'],
  youtube: ['Google-Cloud-Projekt anlegen; YouTube Data API v3 und YouTube Analytics API aktivieren.',
    'Google Auth Platform: Branding, Audience (External) und Data Access mit den Scopes youtube.readonly und yt-analytics.readonly.',
    'Unter Clients einen Client vom Typ Web application anlegen und die Weiterleitungs-URI oben bei „Authorized redirect URIs“ eintragen.',
    'Im Status Testing höchstens 100 Testnutzer; deren Zustimmung läuft nach 7 Tagen ab.',
    'Für alle Talents: Publish app und Verifizierung im Verification Center. Kontingent 10.000 Einheiten je Tag; mehr über das YouTube Audit.',
    'Hier Client-ID und Clientschlüssel eintragen.'],
  pinterest: ['Mit einem Business-Konto bei developers.pinterest.com anmelden.',
    'Unter My apps die Developer Terms akzeptieren, Connect app, Antrag ausfüllen (Trial access wird geprüft).',
    'Nach der Freigabe stehen App ID und App secret unter My apps.',
    'Unter My apps › Manage › Configure › Redirect URIs die Weiterleitungs-URI oben eintragen.',
    'Trial: höchstens 1.000 Anfragen je Tag für die ganze App. Ob sich im Trial fremde Konten verbinden dürfen: nicht geprüft. Für alle Talents: Upgrade auf Standard.',
    'Hier App-ID und App-Secret eintragen.'],
  tiktok: ['Bei developers.tiktok.com unter Manage apps › Connect an app eine App anlegen, Eigentümer: Organisation.',
    'Basic information ausfüllen, Platforms: Web, URL properties bestätigen.',
    'Add products › Login Kit: die Weiterleitungs-URI oben eintragen; Scopes user.info.basic, user.info.stats und video.list hinzufügen.',
    'Client key und Client secret stehen auf der App-Seite (genaue Stelle nicht geprüft).',
    'Testen nur mit Sandbox und bis zu 10 eigenen Konten; für Talents braucht es das App Review.',
    'Hier Client Key und Client Secret eintragen.']
};

// KI-Zugang (Formular wie ALLY 8 „KI und Superadmin einsetzen“: Quelle nur für Superadmins, Schlüssel nur eingeben)
const kiZugang = (K, superadmin) => {
  const kunde = String(K.ki_schluessel || '') === 'kunde', AN = String(K.anbieter_name || '').trim();
  const felder = [];
  if (superadmin) felder.push({ typ: 'auswahl', name: 'quelle', label: 'Schlüssel von', wert: kunde ? 'kunde' : 'plattform', optionen: [opt('plattform', 'Anbieter' + (AN ? ' (' + AN + ')' : '')), opt('kunde', 'Kundschaft')] });
  felder.push({ typ: 'passwort', name: 'schluessel', label: 'Anthropic API-Schlüssel', pflicht: true, autocomplete: 'new-password', info: 'Wird vor dem Speichern geprüft und ersetzt den bisherigen Schlüssel. ' + KEIN_ZEIGEN });
  return [{ typ: 'paare', eintraege: [{ label: 'KI-Zugang', wert: kunde ? 'Eigener Anthropic-Schlüssel' : 'Anbieter' + (AN ? ' (' + AN + ')' : '') },
      { label: 'Zuletzt geprüft', wert: K.zugang_geprueft ? String(K.zugang_geprueft) + ' Uhr' : '–' }] },
    { typ: 'formular', id: 'ki-zugang', aktion: 'ki_zugang', spalten: 2, frage: 'KI-Zugang jetzt prüfen und speichern?', felder,
      info: 'Den Schlüssel erstellst du in der Claude Console (platform.claude.com).' + (superadmin ? '' : ' Mit eigenem Schlüssel rechnet Anthropic die KI-Kosten direkt mit euch ab.'),
      knoepfe: [{ text: 'Prüfen und speichern', art: 'neben' }] }];
};

for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object') continue;
  const AB = Array.isArray(I.abschnitte) ? I.abschnitte : null;
  if (!AB) continue;
  const ersetze = (id, neu) => { const i = AB.findIndex(a => a && a.id === id); if (i < 0) AB.push(...neu); else AB.splice(i, 1, ...neu); };

  // ---------- KI und Budget: KI-Zugang (nur wer den Schlüssel ändern darf) ----------
  if (bereich === 'ki' && D.ki && D.ki.ok === true && D.ki.darf_schluessel_aendern === true && !AB.some(a => a && a.id === 'ki-zugang')) {
    const i = AB.findIndex(a => a && a.id === 'modelle');
    AB.splice(i < 0 ? AB.length : i + 1, 0, { id: 'ki-zugang', titel: 'KI-Zugang', offen_standard: false, info: 'Anthropic-Schlüssel für alle KI-Aufgaben.', inhalt: kiZugang(D.ki, D.ki.superadmin === true) });
  }

  // ---------- Administration › Plattform-Apps (nur Superadmin; Stefan 21.10.2026: bisher auf der Seite „Superadmin“): Meta-App, Plattform-Apps, Meta-Rechtstexte ----------
  // Die Seite legt „Konto und Design“ nur für Superadmins an; die Daten (sam, mr) lädt die Datenbank nur für sie. Den Anthropic-Schlüssel gibt es unter KI und Budget › KI-Zugang.
  if (bereich === 'plattform-apps' && SA && (Z.sam || Z.mr)) {
    const SM = Z.sam || {}, M = SM.meta && typeof SM.meta === 'object' ? SM.meta : null, IG = SM.meta_ig && typeof SM.meta_ig === 'object' ? SM.meta_ig : null;
    const stand = (id, geheim) => id && geheim ? 'eingerichtet' : id ? 'Geheimcode fehlt' : 'fehlt';
    const neu = [];
    const meta = [];
    if ((M && M.verschluesselung === false) || (IG && IG.verschluesselung === false)) meta.push({ typ: 'text', ton: 'warn', text: 'Die Verschlüsselung ist nicht eingerichtet. Geheimcodes können erst danach gespeichert werden.' });
    if (M) { const id = String(M.app_id || '').trim(), g = M.secret_vorhanden === true;
      meta.push({ typ: 'formular', id: 'sa-meta-fb', aktion: 'sa_meta_app', titel: 'Anmeldung über Facebook: ' + stand(id, g), spalten: 2,
        info: ['App-ID und App-Geheimcode unter App-Einstellungen › Allgemein.', 'Rückleitungsadresse unter Facebook Login › Einstellungen › „Valid OAuth Redirect URIs“ genau so eintragen: ' + String(M.rueckleitung || '–')],
        felder: [{ typ: 'text', name: 'app_id', label: 'App-ID', wert: id, pflicht: true, autocomplete: 'off' }, geheimFeld('app_secret', 'App-Geheimcode', g)], knoepfe: [{ text: 'Speichern', art: 'neben' }] }); }
    if (IG) { const id = String(IG.app_id || '').trim(), g = IG.secret_vorhanden === true;
      meta.push({ typ: 'formular', id: 'sa-meta-ig', aktion: 'sa_meta_ig', titel: 'Anmeldung über Instagram: ' + stand(id, g) + (id && g && IG.secret_seit ? ' (Geheimcode seit ' + IG.secret_seit + ')' : ''), spalten: 2,
        info: ['Instagram-App-ID und Instagram-App-Geheimcode unter Instagram › API-Einrichtung mit Instagram-Login.', 'Dort als Weiterleitungs-URI genau so eintragen (auch ein Schrägstrich am Ende zählt): ' + String(IG.rueckleitung || '–')],
        felder: [{ typ: 'text', name: 'app_id', label: 'Instagram-App-ID', wert: id, pflicht: true, autocomplete: 'off' }, geheimFeld('app_secret', 'Instagram-App-Geheimcode', g)], knoepfe: [{ text: 'Speichern', art: 'neben' }] }); }
    if (meta.length) neu.push({ id: 'meta-app', titel: 'Meta-App', offen_standard: false, info: 'Eine App bei Meta mit zwei Anmeldewegen für Talents. Geheimcodes werden verschlüsselt gespeichert und nicht mehr angezeigt.', inhalt: meta });
    const AP = LI(SM.plattform_apps);
    if (AP.length) {
      const pa = [];
      for (const p of AP) {
        const pl = /^[a-z]{1,20}$/.test(String(p.plattform || '')) ? String(p.plattform) : ''; if (!pl) continue;
        const rl = String(p.rueckleitung || '');
        const info = [String(p.anbieter || ''), /^https:\/\//.test(rl) ? 'Weiterleitungs-URI (genau so bei der Plattform eintragen): ' + rl : 'Die öffentliche Adresse ist nicht eingetragen (Einstellung n8n_oeffentlich).',
          p.hinweis ? String(p.hinweis) : '', p.scopes ? 'Angefragte Berechtigungen: ' + p.scopes : ''].concat(LI(ANLEITUNG[pl]).map((x, i) => (i + 1) + '. ' + x)).filter(Boolean);
        const ti = String(p.name || pl) + ': ' + (p.bereit === true ? 'eingerichtet' : 'noch nicht eingerichtet') + (Number(p.verbunden) > 0 ? ' · ' + Number(p.verbunden) + (Number(p.verbunden) === 1 ? ' verbundener Account' : ' verbundene Accounts') : '');
        if (p.schalter === true) pa.push({ typ: 'formular', id: 'pa-' + pl, aktion: 'sa_plattform_app', werte: { plattform: pl }, titel: ti, info,
          felder: [{ typ: 'anzeige', name: 'app_id_anzeige', label: 'App-ID aus der Meta-App', wert: String(p.app_id || '').trim() || 'noch keine' },
            { typ: 'haken', name: 'an', label: 'Facebook-Seiten auf der Einladungsseite anbieten', an: p.an === true, wert_an: 'ja' }], knoepfe: [{ text: 'Speichern', art: 'neben' }] });
        else pa.push({ typ: 'formular', id: 'pa-' + pl, aktion: 'sa_plattform_app', werte: { plattform: pl }, titel: ti, info, spalten: 2,
          felder: [{ typ: 'text', name: 'app_id', label: String(p.app_id_name || 'App-ID'), wert: String(p.app_id || ''), pflicht: true, autocomplete: 'off' }, geheimFeld('app_secret', String(p.secret_name || 'Geheimcode'), p.secret_vorhanden === true)],
          knoepfe: [{ text: 'Speichern', art: 'neben' }] });
      }
      neu.push({ id: 'plattformen', titel: 'Plattform-Apps', zahl: String(AP.filter(p => p.bereit === true).length) + ' von ' + AP.length, offen_standard: false,
        info: 'Je Plattform eine App beim Anbieter. Bezeichnungen wie in der englischen Doku der Plattform; deutsche Beschriftungen können anders lauten.', inhalt: pa });
    }
    const MR = Z.mr;
    if (MR && MR.ok === true) {
      const EI = MR.einstellungen || {};
      const mi = [{ typ: 'formular', id: 'meta-rechte', aktion: 'sa_meta_rechte', spalten: 2, felder: [
        { typ: 'zahl', name: 'loeschfrist_tage', label: 'Frist bis zur Löschung (Tage)', wert: String(EI.loeschfrist_tage ?? 3), min: 1, max: 30, schritt: 1, pflicht: true, info: 'Standard 3 Tage' },
        { typ: 'email', name: 'kontakt_email', label: 'Kontakt-E-Mail für Datenschutz', wert: String(EI.kontakt_email || ''), autocomplete: 'off' },
        { typ: 'textbereich', name: 'anschrift', label: 'Anschrift des Anbieters', wert: String(EI.anschrift || ''), zeilen: 3 },
        { typ: 'text', name: 'impressum_url', label: 'Impressum (Adresse, optional)', wert: String(EI.impressum_url || ''), platzhalter: 'https://' },
        Object.assign(geheimFeld('ig_basis_secret', 'App-Geheimcode der Instagram-App aus den Grundeinstellungen (optional)', EI.ig_basis_vorhanden === true),
          { info: (EI.ig_basis_vorhanden === true ? 'Hinterlegt. ' : '') + 'Nur nötig, falls Meta die Rückmeldungen der Instagram-App nicht mit dem Instagram-App-Geheimcode signiert (Instagram-App › Settings › Basic › App secret). ' + KEIN_ZEIGEN }),
        { typ: 'auswahl', name: 'freigeben', label: 'Rechtstexte', wert: EI.freigegeben === true ? 'ja' : 'nein', optionen: [opt('nein', 'Entwurf (noch nicht freigegeben)'), opt('ja', 'Freigegeben (geprüft)')],
          info: EI.freigegeben === true && EI.freigegeben_am ? 'Freigegeben am ' + (/^[0-9]{4}-[0-9]{2}-[0-9]{2}/.test(String(EI.freigegeben_am)) ? String(EI.freigegeben_am).slice(0, 10).split('-').reverse().join('.') : String(EI.freigegeben_am)) : 'Erst nach rechtlicher Prüfung freigeben' }],
        info: 'Meta schickt eine Nachricht, wenn ein Talent die App in Facebook oder Instagram entfernt oder die Löschung seiner Daten verlangt. Die Verbindung wird sofort getrennt, die Admins werden informiert, gelöscht wird nach der eingestellten Frist.',
        knoepfe: [{ text: 'Speichern', art: 'neben' }] }];
      const AD = LI(MR.adressen);
      if (AD.length) mi.push({ typ: 'unterueberschrift', text: 'Adressen für Meta', info: 'Bei Meta in den App-Einstellungen eintragen.' },
        // Stefan 21.10.2026: als Tabelle statt Paaren (lange Beschriftungen drückten die Adresse auf einen Buchstaben je Zeile zusammen)
        { typ: 'tabelle', id: 'meta-adressen', titel: 'Adressen für Meta', spalten: [{ schluessel: 'name', titel: 'Wofür' }, { schluessel: 'adresse', titel: 'Adresse' }],
          zeilen: AD.map(x => ({ zellen: { name: { text: String(x.name || ''), neben: String(x.wo || '') }, adresse: String(x.adresse || '') } })),
          sortierung: {}, seite: 1, je_seite: Math.max(1, AD.length), gesamt: AD.length, leer: '' });
      if (MR.letzter_fehler) mi.push({ typ: 'text', ton: 'warn', text: 'Letzte Rückmeldung mit Fehler: ' + String(MR.letzter_fehler) });
      neu.push({ id: 'meta-rechte', titel: 'Meta: Datenlöschung und Rechtstexte', offen_standard: false, inhalt: mi });
    }
    for (const a of neu) { a.schloss = true; a.info = ['Nur für Superadmins sichtbar.'].concat(Array.isArray(a.info) ? a.info : a.info ? [a.info] : []); }
    if (neu.length) neu[0].offen_standard = true;
    AB.push(...neu);
  }

  // ---------- Postfächer: Postfach-Zugang je Platz (ALLY 9) ----------
  if (bereich === 'postfaecher' && (ADM || PFR)) {
    const pfs = LI(W.postfaecher), live = W.plaetze_live === true, frei = LI(W.plaetze_frei);
    const mitPlatz = pfs.filter(p => /^[0-9]{1,9}$/.test(String(p.platz ?? '')));  // Migration 173 (Schritt P, P3): Nummer ohne Grenze
    const zStatus = z => z.ergebnis === 'ok' ? { text: 'Zugang geprüft', ton: 'ok' } : z.ergebnis ? { text: 'Zugang fehlerhaft', ton: 'warn' } : { text: 'noch nicht geprüft', ton: 'grau' };
    const zFelder = (z, mitAdresse) => (mitAdresse ? [{ typ: 'email', name: 'adresse', label: 'Mailadresse', pflicht: true, autocomplete: 'off' }, { typ: 'text', name: 'name', label: 'Name (optional)' }] : []).concat([
      { typ: 'text', name: 'host', label: 'Mailserver (IMAP)', wert: String(z.host || ''), platzhalter: 'imap.beispiel.de', pflicht: true, autocomplete: 'off' },
      { typ: 'text', name: 'port', label: 'Port', wert: String(z.port || 993), pflicht: true },
      { typ: 'text', name: 'benutzer', label: 'Anmeldename', wert: String(z.benutzer || ''), pflicht: true, autocomplete: 'off' },
      { typ: 'passwort', name: 'passwort', label: 'Passwort des Postfachs', pflicht: true, autocomplete: 'new-password', info: 'Geht nur an die Zugangsdaten in n8n. ' + KEIN_ZEIGEN },
      { typ: 'haken', name: 'ssl', label: 'Verschlüsselte Verbindung (SSL/TLS)', an: z.ssl !== false, info: 'Bei Port 993 eingeschaltet lassen', breite: 'voll' }]);
    const zi = [{ typ: 'tabelle', id: 'zugang', titel: 'Postfach-Zugang', spalten: [{ schluessel: 'adresse', titel: 'Postfach' }, { schluessel: 'platz', titel: 'Platz', ausrichtung: 'rechts' },
      { schluessel: 'zugang', titel: 'Zugang' }, { schluessel: 'aktion', titel: 'Aktion' }],
      zeilen: mitPlatz.map(p => { const z = p.zugang || {}; return { zellen: { adresse: { text: String(p.adresse || ''), fett: true, neben: z.host ? z.host + ':' + z.port + ', ' + z.benutzer : '' },
        platz: String(p.platz), zugang: { marke: zStatus(z), neben: [z.geprueft ? 'geprüft ' + z.geprueft : '', z.ordner_stand ? 'Ordner ' + z.ordner_stand : ''].filter(Boolean).join(' · ') },
        aktion: { text: 'Zugang', fenster: 'zugang-' + p.platz } } }; }),
      sortierung: {}, seite: 1, je_seite: Math.max(1, mitPlatz.length), gesamt: mitPlatz.length, leer: 'Kein Postfach mit Platz.' }];
    const fenster = Array.isArray(I.fenster) ? I.fenster : (I.fenster = []);
    for (const p of mitPlatz) {
      const z = p.zugang || {}, pl = String(p.platz), inhalt = [];
      inhalt.push({ typ: 'paare', eintraege: [{ label: 'Stand', wert: zStatus(z).text }, { label: 'Server', wert: z.host ? z.host + ':' + z.port : (z.eingerichtet ? 'vor der Umstellung eingerichtet' : '–') },
        { label: 'Anmeldename', wert: String(z.benutzer || '–') }, { label: 'Zuletzt geprüft', wert: String(z.geprueft || '–') }].concat(z.ergebnis && z.ergebnis !== 'ok' ? [{ label: 'Meldung', wert: String(z.ergebnis) }] : []) });
      inhalt.push({ typ: 'aktion', text: 'Zugang prüfen und Ordner einlesen', aktion: 'pf_zugang_pruefen', werte: { platz: pl } });
      if (live) {
        inhalt.push({ typ: 'formular', id: 'zugang-' + pl, aktion: 'pf_zugang_speichern', werte: { platz: pl }, titel: 'Neue Zugangsdaten', spalten: 2, info: 'Zum Beispiel nach einem Passwortwechsel. Die Verbindung wird sofort geprüft.',
          felder: zFelder(z, false), knoepfe: [{ text: 'Zugang speichern und prüfen', art: 'neben' }] });
        inhalt.push({ typ: 'aktion', text: 'Postfach entfernen', aktion: 'pf_platz_freigeben', werte: { platz: pl }, frage: String(p.adresse || 'Dieses Postfach') + ' wird danach nicht mehr abgerufen, Platz ' + pl + ' wird frei.' });
      } else inhalt.push({ typ: 'text', ton: 'grau', text: 'Ändern und Entfernen erst nach der Umstellung auf Postfach-Plätze.' });
      fenster.push({ id: 'zugang-' + pl, art: 'dialog', titel: 'Zugang ' + String(p.adresse || ''), untertitel: 'Platz ' + pl, inhalt });
    }
    if (live && frei.length) zi.push({ typ: 'formular', id: 'postfach-neu', aktion: 'pf_zugang_speichern', werte: { platz: String(frei[0]) }, titel: 'Neues Postfach (Platz ' + frei[0] + ')', spalten: 2,
      info: 'Die Verbindung wird sofort geprüft. ' + frei.length + ' von 10 Plätzen frei.', felder: zFelder({}, true), knoepfe: [{ text: 'Postfach einrichten', art: 'neben' }] });
    else if (!frei.length) zi.push({ typ: 'text', ton: 'grau', text: W.postfaecher_hoechstzahl_erreicht === true ? 'Die Höchstzahl an Postfächern ist erreicht. Für ein neues Postfach muss ein anderes entfernt werden.' : 'Alle Plätze sind belegt.' });
    ersetze('zugang', [{ id: 'zugang', titel: 'Postfach-Zugang', zahl: String(mitPlatz.length), offen_standard: false,
      info: 'Zugangsdaten (IMAP) gehen nur an die Zugangsdaten in n8n und werden nie angezeigt. Beim Prüfen werden die Ordner des Postfachs eingelesen.', inhalt: zi }]);
  }

  // ---------- Marketing: LinkedIn-App, Trennen, Instagram-Zugang, Icons ----------
  if (bereich === 'marketing') {
    const vo = AB.find(a => a && a.id === 'veroeffentlichen');
    const L = D.li || {}, LA = Z.lia || null, IG = W.instagram || {};
    if (vo && Array.isArray(vo.inhalt)) {
      vo.inhalt = vo.inhalt.filter(b => !(b && b.typ === 'aktion' && b.ziel && b.ziel.seite === 'link' && b.ziel.parameter && b.ziel.parameter.art === 'ig'));
      vo.info = 'Verbinden mit LinkedIn öffnet die Anmeldung bei LinkedIn; danach geht es in der bisherigen Oberfläche weiter. App-Daten, Trennen und Instagram gehen hier. Zugangsdaten werden nie angezeigt.';
      if (L.verbunden) vo.inhalt.push({ typ: 'aktion', text: 'LinkedIn-Profil trennen', aktion: 'li_trennen', frage: 'Dein LinkedIn-Profil trennen? Posten auf dein Profil geht danach erst nach neuem Verbinden.' });
      if (ADM && L.seite_verbunden) vo.inhalt.push({ typ: 'aktion', text: 'Unternehmensseite trennen', aktion: 'li_seite_trennen', frage: 'Die LinkedIn-Unternehmensseite trennen?' });
      if (ADM && LA) {
