  if (bereich === 'postfaecher' && Array.isArray(j.inhalt.fenster)) {
    const pf = j.inhalt.fenster.find(f => f && f.id === 'postfach'), fo = pf && Array.isArray(pf.inhalt) ? pf.inhalt.find(b => b && b.typ === 'formular' && b.id === 'postfach') : null;
    const FE = fo && Array.isArray(fo.felder) ? fo.felder : [], gm = FE.find(f => f && f.name === 'gemeinsam'), eo = FE.find(f => f && f.name === 'entwurf_ordner');
    if (gm) {
      const eigen = gm.an !== true, ordner = eo && eo.typ === 'auswahl' ? (eo.optionen || []).map(o => String(o.wert)) : [];
      const MK = (D.w || {}).mail_kategorien && typeof D.w.mail_kategorien === 'object' ? D.w.mail_kategorien : {};
      const KAT = ['kunde', 'geschaeft', 'spam', 'system_report'];
      const blatt = o => String(o).split(/[./]/).pop().toLowerCase();
      const verschiebt = k => { const g = MK[k] || {}; return /move|verschieb/i.test(String(g.aktion || '')) && String(g.ziel_ordner || '') !== ''; };
      const passend = k => { const g = MK[k] || {}, zo = String(g.ziel_ordner || '');
        if (verschiebt(k)) { if (ordner.includes(zo)) return 'ordner:' + zo;
          const t1 = ordner.find(o => blatt(o) === blatt(zo)) || (k === 'spam' ? ordner.find(o => /^(spam|junk|junk-e-mail|junk e-mail|unerwünscht)$/i.test(blatt(o))) : '');
          return t1 ? 'ordner:' + t1 : 'hinweis'; }
        return /notify|markier|hinweis/i.test(String(g.aktion || '')) ? 'hinweis' : 'nichts'; };
      const fehlend = eigen || !ordner.length ? [] : KAT.filter(k => verschiebt(k) && !ordner.includes(String(MK[k].ziel_ordner))).map(k => String(MK[k].ziel_ordner));
      gm.info = 'Mit Haken gelten für dieses Postfach die gemeinsamen Ordner aller Postfächer' + (fehlend.length ? ' (hier fehlt: ' + fehlend.map(x => '„' + x + '“').join(', ') + ')' : '') +
        '. Ohne Haken gelten die Ordner unten; sie sind mit passenden Ordnern dieses Postfachs vorbelegt.';
      if (!eigen) for (const k of KAT) { const f = FE.find(x => x && x.name === 'einordnung_' + k); if (f) f.wert = passend(k); }
      const pa = pf.inhalt.find(b => b && b.typ === 'paare');
      if (pa && Array.isArray(pa.eintraege)) pa.eintraege.push({ label: 'Einordnung', wert: eigen ? 'Eigene Ordner' : 'Gemeinsam' + (fehlend.length ? ', Ordner fehlt: ' + fehlend.join(', ') : '') });
    }
  }
  // B9 (F2, F10): Einstellungen der Funktionen des Pakets Social-Media Management mit dem Paket im Krümelpfad (Einstellungen › Funktionen › Paket › Seite)
  const FNP = FU.find(f => f && f.ziel === bereich && f.modul === 'talents');
  const PN = FNP && D.module_namen && D.module_namen.talents ? String(D.module_namen.talents) : '';
  if (PN && Array.isArray(j.inhalt.seite.krumen) && j.inhalt.seite.krumen.length === 3)
    j.inhalt.seite.krumen = [j.inhalt.seite.krumen[0], j.inhalt.seite.krumen[1], { text: 'Funktionen' }, { text: PN }, j.inhalt.seite.krumen[2]];
  j.inhalt.leiste = leiste;
  // Runde 2 (Stefan 21.10.2026): Klappzustand der Abschnitte je Unterseite (gleiche Abschnitts-IDs auf verschiedenen Unterseiten teilen sich keinen Zustand mehr)
  const teil = bereich === 'superadmin' ? '' : bereich;
  if (/^[a-z0-9-]{1,40}$/.test(teil)) j.inhalt.seite.zustand_teil = teil; else delete j.inhalt.seite.zustand_teil;
  j.inhalt.seite.leiste_aktiv = aktiv || 'e-keine';
  return { json: j };
});

// Punkte 5j/5k (Stefan 21.10.2026): Darstellung wie in ALLY 8, nur im neuen Aussehen. Ändert nur die Art der Felder, nicht Namen, Werte oder Aktionen:
// Postfächer › Signatur als Editor mit Werkzeugleiste und Schrift-Vorschau (Schriftstapel je Schrift); Unternehmen › Farben mit Farbwähler und Erklärung je Farbe,
// Schrift mit Vorschau; Marketing › Gestaltung der Grafiken: Folienstile als Musterfolien in den Farben und der Schrift des Unternehmens, Akzente mit Erklärung,
// Icons mit Bild (aufklappbar, Zähler). Ohne passende Daten bleibt das Feld wie bisher. Braucht den Baukasten mit den Feldarten signatur, farbe, musterwahl (ALLY 21).
const D = $('Daten laden').first().json || {};
const W = D.w || {};
let Z = {};
try { Z = $('Zusatzdaten laden').first().json || {}; } catch (e) { Z = {}; }
const LI = x => Array.isArray(x) ? x : [];
const HEX = /^#[0-9A-Fa-f]{6}$/;
// Stefan 02.11.2026: Farbfelder heißen nach dem, was sie in Ally ändern; das i-Symbol nennt die übrigen Stellen (Berichte, Grafiken, Einladungsseite).
const FARB_NAME = { farbe_dunkel: 'Kopfleiste', farbe_text_auf_dunkel: 'Schrift in der Kopfleiste', farbe_akzent: 'Markierungen', farbe_akzent_dunkel: 'Knöpfe und Links',
  farbe_hell: 'Seitenhintergrund', farbe_grau: 'Nebentext', farbe_warnung: 'Warnungen und Fehler' };
const FARB_INFO = { farbe_dunkel: 'Hintergrund der Kopfleiste in Ally. Auch dunkle Flächen und Überschriften in Berichten, Grafiken und auf der Einladungsseite.',
  farbe_text_auf_dunkel: 'Schrift und Symbole in der Kopfleiste und auf allen dunklen Flächen.',
  farbe_akzent: 'Punkte, Ladebalken und ausgewählte Zeilen in Ally. Auch Hervorhebungen und Flächen in Grafiken.',
  farbe_akzent_dunkel: 'Knöpfe, Links und aktive Kacheln in Ally, Balken in Berichten. Muss mit weißer Schrift gut lesbar sein.',
  farbe_hell: 'Hintergrund der Seiten und Hinweisfelder in Ally. Auch helle Flächen in Berichten und Grafiken.',
  farbe_grau: 'Kleine Beschriftungen, Hinweise und Tabellenköpfe in Berichten und auf der Einladungsseite.',
  farbe_warnung: 'Fehlertexte, Warn-Knöpfe und Überschreitungen.' };
// Neutrales Standard-CD wie in ALLY 8 / CD 1 (Vorschau, solange ein Unternehmen keine eigenen Farben hat)
const STANDARD = { farbe_dunkel: '#1F2933', farbe_text_auf_dunkel: '#FFFFFF', farbe_akzent: '#52606D', farbe_akzent_dunkel: '#323F4B', farbe_hell: '#F5F7FA', farbe_grau: '#9AA5B1', farbe_warnung: '#B54708' };
// Fehler Nr. 20 (Stefan 02.11.2026, 08:33; Auswahl „Inter, ohne Systemschrift“): Schrift als Ausklappliste gängiger Google-Schriften mit Vorschau;
// ein gespeicherter Name außerhalb der Liste bleibt wählbar. Ohne gespeicherte Schrift steht Inter da (Standard wie CD 1).
const SCHRIFT_LISTE = ['Inter', 'Montserrat', 'Open Sans', 'Roboto', 'Lato', 'Raleway', 'Poppins', 'Nunito', 'Work Sans', 'Source Sans 3'];
const AKZENTE = { punkte: 'Feines Punktmuster im Hintergrund', boegen: 'Kreisbögen in der Ecke', gross_icon: 'Das Icon der Folie groß und blass hinter dem Text', icons: 'Passende Icons aus der Auswahl unten' };
const SCHRIFTEN = LI(W.mail_schriften);
const stapel = k => { const s = SCHRIFTEN.find(x => x && String(x.schluessel) === String(k)); return s && s.stapel ? String(s.stapel) : ''; };
const UN = LI(W.unternehmen);
const SVG = Z.icons_svg && typeof Z.icons_svg === 'object' ? Z.icons_svg : {};

const postfach = f => {
  const fs = LI(f.felder);
  const sch = fs.find(x => x && x.name === 'schrift'), gr = fs.find(x => x && x.name === 'schrift_groesse');
  if (sch && sch.typ === 'auswahl') sch.optionen = LI(sch.optionen).map(o => stapel(o.wert) ? Object.assign({}, o, { stapel: stapel(o.wert) }) : o);
  const i = fs.findIndex(x => x && x.name === 'signatur_html' && x.typ === 'textbereich');
  if (i < 0) return;
  fs[i] = { typ: 'signatur', name: 'signatur_html', label: 'Signatur', wert: String(fs[i].wert || ''), breite: 'voll', schrift_feld: sch ? 'schrift' : undefined, groesse_feld: gr ? 'schrift_groesse' : undefined,
    schrift_stapel: sch ? stapel(sch.wert) : '', schrift_groesse: gr ? Number(gr.wert) || 13 : 13,
    info: ['Aus dem Mailprogramm hineinkopieren oder hier gestalten.', '{Name} wird im Entwurf durch den Namen der Person ersetzt, die ihn anfordert.',
      'Ein Logo über „Bild“ mit dem Link zur Bilddatei einfügen (z. B. von der eigenen Website); ein Klick auf ein Bild ändert Link oder Breite.',
      'Mailtext und Signatur stehen im Entwurf in der Schrift des Postfachs; feste Farben werden dabei zurückgesetzt.'] };
};
const cd = f => {
  for (const x of LI(f.felder)) {
    if (!x || typeof x !== 'object') continue;
    if (FARB_INFO[x.name] && x.typ === 'text') {
      Object.assign(x, { typ: 'farbe', label: FARB_NAME[x.name] || x.label, info: FARB_INFO[x.name] }), delete x.platzhalter, delete x.autocomplete;
      // Fehler Nr. 19 (Stefan 02.11.2026, 08:30): leere Farbfelder mit den Standardfarben vorbelegt
      if (!HEX.test(String(x.wert || ''))) x.wert = STANDARD[x.name];
    } else if (x.name === 'schrift' && x.typ === 'text') {
      const g = String(x.wert || '').trim(), wahl = /^[A-Za-z0-9 ]{1,60}$/.test(g) ? g : 'Inter';
      Object.assign(x, { typ: 'auswahl', wert: wahl, ausklappliste: true, schrift_vorschau: true, info: 'Gilt für Ally, Berichte und Grafiken.',
        optionen: (SCHRIFT_LISTE.includes(wahl) ? SCHRIFT_LISTE : [wahl].concat(SCHRIFT_LISTE)).map(t => ({ wert: t, text: t })) });
      delete x.platzhalter; delete x.autocomplete;
    }
  }
};
const gestaltung = f => {
  const fs = LI(f.felder);
  const u = UN.find(x => String(x.id) === String((f.werte || {}).id)) || {};
  const c = u.cd || {}, F0 = c.farben || {}, G = c.gestaltung || {};
  const fw = k => HEX.test(String(F0[k] || '')) ? String(F0[k]).toUpperCase() : STANDARD[k];
  const sch = /^[A-Za-z0-9 ]{1,60}$/.test(String(c.schrift || '')) ? String(c.schrift) : '';
  const STILE = [['dunkel', 'Dunkel', fw('farbe_dunkel'), fw('farbe_text_auf_dunkel'), fw('farbe_akzent')], ['hell', 'Hell', fw('farbe_hell'), fw('farbe_dunkel'), fw('farbe_akzent_dunkel')],
    ['akzent', 'Akzentfarbe', fw('farbe_akzent'), fw('farbe_dunkel'), fw('farbe_dunkel')]];
  const idx = fs.findIndex(x => x && /^stil__/.test(String(x.name || '')) && x.typ === 'haken');
  if (idx >= 0) {
    const an = n => { const h = fs.find(x => x && x.name === 'stil__' + n); return h ? h.an === true : false; };
    const hg = LI(c.hintergruende).length > 0;
    const mw = { typ: 'musterwahl', name: 'stile', label: 'Folienstile', breite: 'voll', info: hg ? 'Wechselt mit den eigenen Hintergründen ab; ohne Stil nur Hintergründe.' : 'Mindestens ein Stil.',
      optionen: STILE.map(([k, t, bg, tx, ak]) => ({ name: 'stil__' + k, text: t, an: an(k), muster: { hintergrund: bg, text: tx, akzent: ak, schrift: sch, punkte: G.punkte !== false, boegen: G.boegen !== false } })) };
    const rest = fs.filter(x => !(x && /^stil__/.test(String(x.name || '')) && x.typ === 'haken'));
    rest.splice(idx, 0, mw);
    f.felder = rest;
    f.spalten = 2;
    if (/Folienstil/.test(String(f.info || ''))) delete f.info;
  }
  for (const x of LI(f.felder)) {
    if (x && x.typ === 'haken' && AKZENTE[x.name] && !x.neben) x.neben = AKZENTE[x.name];
    if (x && x.typ === 'haken' && x.name === 'icons') x.label = 'Icons verwenden';
    if (x && x.name === 'icon_auswahl' && x.typ === 'mehrfach' && Object.keys(SVG).length) {
      x.optionen = LI(x.optionen).map(o => SVG[o.wert] ? Object.assign({}, o, { svg: String(SVG[o.wert]) }) : o);
      x.label = 'Icons'; x.aufklappbar = true; x.aufklappen_text = 'Icons auswählen';
    }
  }
};
// Fehler Nr. 24 (Stefan 02.11.2026, Auswahl „Ja, so bauen“): Absender für Systemnachrichten – bei einem vorhandenen Postfach sendet Ally über dessen Versand
// (Migration 198); Server, Anmeldename und Passwort nur beim eigenen Postfach nur für Systemnachrichten.
const SY_NUR_EIGEN = ['smtp_host', 'smtp_port', 'smtp_benutzer', 'passwort'];
const sy = f => {
  for (const x of LI(f.felder)) if (x && SY_NUR_EIGEN.includes(x.name)) x.zeigen_wenn = { feld: 'quelle', werte: ['eigen'] };
  f.info = 'Bei einem vorhandenen Postfach sendet Ally über dessen Versand; geprüft wird mit einer Testnachricht. Server, Anmeldename und Passwort braucht nur ein eigenes Postfach. '
    + 'Das Passwort wird verschlüsselt in den Zugangsdaten für den Versand gespeichert, nicht in der Datenbank.';
  f.knoepfe = [{ text: 'Speichern' }];
};
const durch = bl => { for (const b of LI(bl)) {
  if (!b || typeof b !== 'object') continue;
  if (b.typ === 'formular' && b.aktion === 'postfach') postfach(b);
  if (b.typ === 'formular' && b.aktion === 'cd') cd(b);
  if (b.typ === 'formular' && b.aktion === 'cd_gestaltung') gestaltung(b);
  if (b.typ === 'formular' && b.aktion === 'sy_absender_speichern') sy(b);
} };
// App-Symbol als Bild statt Text (Stefan 21.10.2026, 09:28; Vorgabe Content-Agent): Baustein bilder mit symbol (ALLY 20 <basis>/symbol, ohne eigenes Symbol die Ersatz-Bildmarke);
// version aus dem Änderungszeitpunkt, damit nach dem Hochladen das neue Bild kommt. Größe und Datum klein darunter.
const AS = D.app_symbol && typeof D.app_symbol === 'object' ? D.app_symbol : null;
const appSymbol = a => {
  const b0 = LI(a.inhalt)[0];
  if (!b0 || b0.typ !== 'paare' || !LI(b0.eintraege).some(e => e && e.label === 'Aktuell')) return;
  const eigen = !!AS && AS.eigen === true;
  const asV = eigen ? String(AS.am || '').replace(/[^0-9]/g, '').slice(0, 16) : '';
  a.inhalt[0] = { typ: 'bilder', eintraege: [{ titel: eigen ? 'Eigenes Symbol' : 'Bildmarke aus dem Corporate Design', alt: 'Aktuelles App-Symbol', symbol: { version: asV || 'cd' },
    neben: eigen ? Number(AS.breite) + ' × ' + Number(AS.hoehe) + ' Pixel' + (AS.am ? ' · seit ' + String(AS.am) : '') : 'solange kein eigenes Symbol hochgeladen ist' }] };
};
return $input.all().map(it => {
  const I = it.json && it.json.inhalt;
  if (I && typeof I === 'object') {
    durch(I.bloecke);
    for (const a of LI(I.abschnitte)) { durch(a && a.inhalt); if (a && a.id === 'app-symbol') appSymbol(a); }
    for (const f of LI(I.fenster)) durch(f && f.inhalt);
  }
  return it;
});

// Verlauf-Feld (ALLY 23, BA10, Migration 69): KI und Budget › Ally-Chat für Talents – Feld „Chatverlauf aufbewahren (Tage)“ (Aktion ki_talent_verlauf,
// 7 bis 3650, Standard 90; speichern darf nur Admin, prüft die Datenbank). Ergänzt nur den Abschnitt talent-chat nach dem Formular talent-ki-standard; sonst unverändert.
const aus = $input.all().map(x => x.json);
const TC = ($('Daten laden').first().json || {}).tc || {};
for (const j of aus) {
  const ab = j && j.inhalt && Array.isArray(j.inhalt.abschnitte) ? j.inhalt.abschnitte.find(a => a && a.id === 'talent-chat') : null;
  if (!ab || !Array.isArray(ab.inhalt) || ab.inhalt.some(b => b && b.id === 'talent-chat-verlauf')) continue;
  const i = ab.inhalt.findIndex(b => b && b.id === 'talent-ki-standard');
  ab.inhalt.splice(i < 0 ? 0 : i + 1, 0, { typ: 'formular', id: 'talent-chat-verlauf', aktion: 'ki_talent_verlauf', knoepfe_in_reihe: true,
    felder: [{ typ: 'zahl', name: 'tage', label: 'Chatverlauf aufbewahren (Tage)', wert: String(Number.isInteger(TC.verlauf_tage) ? TC.verlauf_tage : 90), min: 7, max: 3650, schritt: 1, pflicht: true,
      info: 'Standard 90 Tage. Ältere Nachrichten der Talents im Ally-Chat werden täglich gelöscht. Der Chatverlauf ist Teil des Datenexports eines Talents (DSGVO).' }],
    knoepfe: [{ text: 'Speichern', art: 'neben' }] });
}
return aus.map(json => ({ json }));

