-- Testdaten laden (ALLY 23, Migration 79, Stefan 21.10.2026): Stand der Testdaten für die Seite Administration › Testdaten und den Eintrag in Leiste/Übersicht.
-- ally_testdaten_ui liefert nur für Superadmins etwas (sonst NULL). Nur auf der Übersicht und der Seite testdaten. $1 Sitzung, $2 Bereich.
SELECT CASE WHEN $2::text IN ('', 'testdaten') THEN ally_testdaten_ui($1::text) END AS td;

parameters.jsCode:
// Testdaten-Seite (ALLY 23, Migration 79, Stefan 21.10.2026): Einstellungen › Administration › Testdaten, nur für Superadmins (für alle anderen weder Seite noch Eintrag).
// Ergänzt die fertige Seite, ohne andere Knoten zu ändern: Eintrag in Leiste und Übersicht, eigene Seite (bereich testdaten) mit Stand und Ein/Aus (td_ein, td_aus).
// Daten aus „Testdaten laden“ (ally_testdaten_ui, nur Superadmin).
// Migration 168 (Bauplan B7, Stefan 28.10.2026): ohne Test-Logins (bis vor 168 Abschnitt „Test-Logins“ mit td_passwort); Formular direkt auf der Seite wie vorher (kachel: false),
// Anzahl Talents als Ausklappliste.
const E = $('Start').first().json;
const bereich = String((E.parameter || {}).bereich || '');
let TD = null;
try { TD = ($input.first().json || {}).td; } catch (e) { TD = null; }
const j = $('Felder wie ALLY 8').first().json;
if (!TD || typeof TD !== 'object' || !j || !j.inhalt || !j.inhalt.seite) return [{ json: j }];
const I = j.inhalt;
const ziel = { seite: 'einstellungen', parameter: { bereich: 'testdaten' } };
// Leiste: Eintrag unter Administration
const L = I.leiste;
if (L && Array.isArray(L.gruppen)) {
  let g = L.gruppen.find(x => x && x.id === 'e-administration');
  if (!g) { g = { id: 'e-administration', name: 'Administration', eintraege: [] }; L.gruppen.push(g); }
  if (!g.eintraege.some(e => e && e.schluessel === 'e-administration-testdaten')) g.eintraege.push({ schluessel: 'e-administration-testdaten', text: 'Testdaten', ziel });
}
// Übersicht: Eintrag in der Liste unter Administration
if (!bereich && Array.isArray(I.abschnitte)) {
  const adm = I.abschnitte.find(a => a && a.id === 'administration');
  const li = adm && Array.isArray(adm.inhalt) ? adm.inhalt.find(b => b && b.typ === 'liste') : null;
  if (li && Array.isArray(li.eintraege) && !li.eintraege.some(e => e && e.ziel && e.ziel.parameter && e.ziel.parameter.bereich === 'testdaten'))
    li.eintraege.push({ text: 'Testdaten', ziel, ziel_text: 'Öffnen' });
}
if (bereich !== 'testdaten') return [{ json: j }];

// ---------- eigene Seite ----------
const an = TD.aktiv === true;
const groesse = [10, 50, 100].includes(Number(TD.groesse)) ? String(TD.groesse) : '10';
const A = TD.anzahl && typeof TD.anzahl === 'object' ? TD.anzahl : {};
const zahl = v => Number(v || 0).toLocaleString('de-DE');
const stand = [{ label: 'Status', wert: an ? 'Eingeschaltet' : 'Ausgeschaltet' }];
if (an) stand.push({ label: 'Umfang', wert: zahl(TD.talents) + ' Talents, ' + zahl(TD.personen) + ' Test-Manager, ' + zahl(TD.kampagnen) + ' Kampagnen' + (A.beitraege ? ', ' + zahl(A.beitraege) + ' Beiträge' : '') },
  { label: 'Eingeschaltet am', wert: String(TD.erzeugt_am || '–') });
else if (TD.entfernt_am) stand.push({ label: 'Ausgeschaltet am', wert: String(TD.entfernt_am) });
const wahl = { typ: 'auswahl', name: 'groesse', label: 'Anzahl Talents', wert: groesse, optionen: [{ wert: '10', text: '10 Talents' }, { wert: '50', text: '50 Talents' }, { wert: '100', text: '100 Talents' }],
  ausklappliste: true, info: 'Dazu legt Ally 5 Test-Manager an, auf die die Talents verteilt werden.' };
const inhalt = [{ typ: 'paare', eintraege: stand }];
if (TD.paket !== true) inhalt.push({ typ: 'text', ton: 'grau', text: 'Testdaten brauchen das Paket Talents.' });
else if (!an) inhalt.push({ typ: 'formular', id: 'td-ein', aktion: 'td_ein', spalten: 2, knoepfe_in_reihe: true, felder: [wahl], knoepfe: [{ text: 'Einschalten', art: 'neben' }],
  frage: 'Testdaten jetzt einschalten? Sie sind in allen Listen als Testdaten gekennzeichnet.' });
else inhalt.push({ typ: 'formular', id: 'td-neu', aktion: 'td_ein', spalten: 2, knoepfe_in_reihe: true, felder: [wahl], knoepfe: [{ text: 'Neu erzeugen', art: 'neben' }],
    frage: 'Testdaten neu erzeugen? Die bisherigen Testdaten und alles, was daran geändert wurde, werden dabei entfernt.' },
  { typ: 'aktion', text: 'Ausschalten', aktion: 'td_aus', frage: 'Testdaten ausschalten? Alle Testdaten werden vollständig entfernt. Echte Daten bleiben unverändert.' });
const abschnitte = [{ id: 'stand', titel: 'Testdaten', offen_standard: true, schloss: true, kachel: false,
  info: ['Nur für Superadmins sichtbar.', 'Beispieldaten, um Ally vor dem Start auszuprobieren. Sie lösen keine Abrufe bei Plattformen, keine Mails, Chat-Nachrichten, Erinnerungen, Briefings, KI-Aufträge, Kalender-Einträge oder Exporte aus.',
    'Ausschalten entfernt alle Testdaten vollständig, auch Änderungen daran.'], inhalt }];
I.seite = Object.assign({}, I.seite, { titel: 'Testdaten', beschreibung: 'Beispieldaten zum Ausprobieren, jederzeit vollständig entfernbar.',
  krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: 'Einstellungen', ziel: { seite: 'einstellungen' } }, { text: 'Testdaten' }],
  zustand_teil: 'testdaten', leiste_aktiv: 'e-administration-testdaten' });
delete I.bloecke;
I.abschnitte = abschnitte;
